window.BANCO.push(

/* ============================ 4.1 — Patologia do Trabalho ============================ */

{ id: 'q-4.1-010', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de fundição, 52 anos, com 20 anos de exposição a fumos metálicos, apresenta quadro pulmonar em investigação. O médico do trabalho precisa classificar o agravo quanto à relação com o trabalho antes de decidir sobre notificação e comunicação. Sobre os conceitos de doença profissional e doença do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Doença profissional é aquela desencadeada pelo exercício peculiar a determinada atividade, ao passo que doença do trabalho é a adquirida em função de condições especiais em que o trabalho é realizado, e ambas se equiparam a acidente do trabalho para fins legais.', ok: true,
      why: 'Correta. A distinção clássica separa a doença típica da profissão daquela ligada às condições em que o trabalho se dá, mas as duas recebem o mesmo tratamento jurídico de acidente do trabalho.' },
    { t: 'Doença profissional exige comprovação de incapacidade laborativa permanente para ser assim classificada.', ok: false,
      why: 'Errada. A classificação depende do nexo com a atividade, não do grau ou da permanência da incapacidade, que é questão distinta e posterior.' },
    { t: 'Doença do trabalho é sinônimo de doença degenerativa e por isso nunca gera direito previdenciário acidentário.', ok: false,
      why: 'Errada. Doenças degenerativas e as inerentes a grupo etário são justamente as excluídas do conceito; doença do trabalho é conceito diverso e gera repercussão acidentária.' },
    { t: 'Doença endêmica é sempre considerada doença do trabalho quando acomete trabalhador da região onde é endêmica.', ok: false,
      why: 'Errada. A doença endêmica só é considerada relacionada ao trabalho quando resulta de exposição determinada pela natureza do trabalho, e não da mera residência em área endêmica.' },
    { t: 'A ausência do agravo em lista oficial impede em definitivo o reconhecimento do nexo ocupacional.', ok: false,
      why: 'Errada. A lista é referência, e existe previsão expressa de reconhecimento de agravo não listado quando demonstrada a relação com as condições de trabalho.' }
  ],
  comentario: 'Doença profissional é a típica da profissão (causa peculiar à atividade); doença do trabalho decorre das condições especiais em que o trabalho é executado. Ambas se equiparam a acidente do trabalho. Ficam de fora as degenerativas, as inerentes ao grupo etário, as que não produzem incapacidade e as endêmicas sem exposição determinada pelo trabalho.',
  pegadinha: 'A exclusão da doença endêmica é parcial: se a exposição decorrer da natureza do trabalho, o nexo se estabelece. Quem decora a lista de exclusões sem a ressalva erra.',
  refs: ['Lei 8.213/91 — conceitos de doença profissional e do trabalho', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-011', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Em uma mesma manhã de ambulatório, o médico do trabalho atende: um trabalhador com mesotelioma pleural após exposição a asbesto; um operador de caldeira com câncer de pulmão, tabagista de longa data, exposto a fumos de combustão; e uma auxiliar administrativa com crise de asma desencadeada pela poeira do prédio em reforma, com asma diagnosticada na infância. Segundo a classificação de Schilling, os três casos correspondem, respectivamente, a:',
  alts: [
    { t: 'Grupo I, Grupo II e Grupo III.', ok: true,
      why: 'Correta. Mesotelioma exige exposição a asbesto (causa necessária); o câncer de pulmão tem o trabalho como um entre vários fatores de risco, ao lado do tabagismo; e a asma preexistente apenas agravada pelas condições do ambiente é doença comum desencadeada ou agravada pelo trabalho.' },
    { t: 'Grupo I, Grupo I e Grupo II.', ok: false,
      why: 'Errada. Câncer de pulmão em tabagista exposto a fumos não tem o trabalho como causa necessária, e a asma preexistente agravada não é caso de fator contributivo, e sim de agravamento.' },
    { t: 'Grupo II, Grupo III e Grupo I.', ok: false,
      why: 'Errada em todos os termos. Mesotelioma é o exemplo mais citado de causa necessária, e a ordem proposta inverte a lógica dos três grupos.' },
    { t: 'Grupo III, Grupo II e Grupo I.', ok: false,
      why: 'Errada. Mesotelioma jamais seria doença comum agravada pelo trabalho, e asma preexistente agravada não é doença com o trabalho como causa necessária.' },
    { t: 'Todos pertencem ao Grupo II, pois em todos há mais de um fator de risco envolvido.', ok: false,
      why: 'Errada. A presença de múltiplos fatores não uniformiza a classificação; o critério decisivo é o papel do trabalho: necessário, contributivo ou agravante.' }
  ],
  comentario: 'A chave de Schilling é o papel causal do trabalho. Grupo I: sem trabalho, não há doença (mesotelioma, silicose, saturnismo). Grupo II: trabalho como fator de risco somado a outros (câncer de pulmão, hipertensão). Grupo III: doença comum preexistente desencadeada ou agravada pelo trabalho (asma da infância piorada por poeira).',
  pegadinha: 'A asma é a armadilha: asma ocupacional verdadeira, com sensibilização no trabalho, seria de causa necessária; asma preexistente apenas agravada cai no grupo de agravamento. O enunciado avisa que o diagnóstico é da infância.',
  refs: ['Schilling, R.S.F.', 'Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde'] },

{ id: 'q-4.1-012', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Um médico do trabalho recebe trabalhador com queixa de tremor e alteração de memória e suspeita de intoxicação crônica. Ao estruturar a anamnese ocupacional, deve orientar-se por qual princípio?',
  alts: [
    { t: 'A história ocupacional deve abranger toda a trajetória de trabalho do indivíduo, incluindo empregos anteriores, informais e atividades extralaborais, com descrição de tarefas reais, agentes, tempo e intensidade de exposição.', ok: true,
      why: 'Correta. Restringir-se ao emprego atual é o erro mais frequente; agravos de longa latência costumam ter origem em exposições antigas e em vínculos informais não registrados.' },
    { t: 'Basta registrar a ocupação declarada e o setor atual, pois a descrição formal do cargo reflete a exposição real.', ok: false,
      why: 'Errada. Denominação de cargo raramente descreve a tarefa efetivamente executada; é preciso perguntar o que a pessoa realmente faz.' },
    { t: 'Atividades de lazer e trabalho doméstico devem ser desconsideradas para não confundir o raciocínio de nexo.', ok: false,
      why: 'Errada. Exposições não ocupacionais precisam ser levantadas exatamente para permitir avaliar sua contribuição, e não para serem ignoradas.' },
    { t: 'A anamnese ocupacional só se justifica quando já existe hipótese diagnóstica firmada de doença ocupacional.', ok: false,
      why: 'Errada. A história ocupacional é parte da anamnese de qualquer paciente e serve para levantar a hipótese, não apenas para confirmá-la.' },
    { t: 'A informação do trabalhador sobre a exposição deve ser descartada quando divergir do documento da empresa.', ok: false,
      why: 'Errada. A divergência é dado clínico relevante e deve motivar investigação do posto de trabalho, não descarte automático do relato.' }
  ],
  comentario: 'A anamnese ocupacional é cronológica e exaustiva: todas as ocupações desde a primeira, formais e informais, com tarefa real, agentes, tempo, intensidade, uso de proteção e sintomas correlacionados. Deve incluir exposições extralaborais e ambientais.',
  pegadinha: 'A ideia de que descrever exposições não ocupacionais "enfraquece o nexo" leva o candidato a marcar a opção que manda ignorá-las. Ocorre o contrário: o nexo se fortalece quando as alternativas causais são investigadas e afastadas.',
  refs: ['Mendes, R. — Patologia do Trabalho', 'Anamnese ocupacional — Ministério da Saúde'] },

{ id: 'q-4.1-013', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador aposentado procura serviço de saúde 28 anos após ter trabalhado em estaleiro com isolamento térmico, referindo dispneia e dor torácica, com diagnóstico recente de mesotelioma. A empresa alega que o afastamento da exposição há quase três décadas afasta o nexo. Sobre períodos de latência e de indução, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O período de latência longo é característico de neoplasias ocupacionais e o intervalo referido é compatível com o mesotelioma, de modo que o afastamento antigo da exposição reforça, e não afasta, a plausibilidade do nexo.', ok: true,
      why: 'Correta. O raciocínio de nexo em câncer ocupacional exige latência compatível; intervalo de décadas é exatamente o esperado nesse tumor.' },
    { t: 'Latência e indução são sinônimos e correspondem ao tempo entre o início dos sintomas e o diagnóstico.', ok: false,
      why: 'Errada. Indução é o tempo entre a exposição e o início do processo patológico; latência inclui também o período até a manifestação clínica. Nenhum dos dois se refere ao atraso diagnóstico.' },
    { t: 'Doenças com período de latência longo devem ser classificadas como doenças degenerativas e excluídas do conceito de doença do trabalho.', ok: false,
      why: 'Errada. Latência longa não converte a doença em degenerativa; a exclusão legal se refere a processos próprios do envelhecimento sem relação com a exposição.' },
    { t: 'Se o trabalhador está aposentado, a doença deixa de ter repercussão previdenciária acidentária.', ok: false,
      why: 'Errada. O reconhecimento da relação com o trabalho independe do vínculo estar ativo, e há repercussões próprias mesmo após a aposentadoria.' },
    { t: 'Uma latência curta jamais é compatível com agravos ocupacionais, que por definição exigem exposição prolongada.', ok: false,
      why: 'Errada. Há agravos ocupacionais de latência curtíssima, como intoxicações agudas, dermatites irritativas e a silicose aguda por exposição maciça.' }
  ],
  comentario: 'Indução: intervalo entre a exposição e o início do processo biológico. Latência: intervalo entre a exposição e a manifestação clínica detectável. Em cânceres ocupacionais a latência é medida em décadas, e é justamente essa compatibilidade temporal que sustenta o nexo — a exposição remota não o enfraquece.',
  pegadinha: 'O argumento defensivo "faz muito tempo, logo não tem relação" é o inverso do raciocínio correto para doenças de longa latência.',
  refs: ['Mendes, R. — Patologia do Trabalho', 'Atlas do Câncer Relacionado ao Trabalho'] },

{ id: 'q-4.1-014', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Ao discutir com a área jurídica da empresa o reconhecimento de agravos relacionados ao trabalho, o médico é questionado sobre o papel da Lista de Doenças Relacionadas ao Trabalho do Ministério da Saúde. Assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A presença de um agravo na lista dispensa a avaliação individual da exposição, bastando o diagnóstico da doença para caracterizar a origem ocupacional.', ok: true,
      why: 'É a afirmação FALSA, portanto a resposta. A lista indica agentes e doenças com relação reconhecida, mas o nexo individual sempre exige demonstração de exposição compatível no caso concreto.' },
    { t: 'A lista é organizada relacionando agentes etiológicos ou fatores de risco de natureza ocupacional às respectivas doenças.', ok: false,
      why: 'Verdadeira. Essa é justamente a estrutura da lista, que permite consulta pelo agente ou pela doença.' },
    { t: 'A lista incorpora a lógica de Schilling, contemplando doenças em que o trabalho é causa necessária e também aquelas em que é fator contributivo ou de agravamento.', ok: false,
      why: 'Verdadeira. A classificação por grupos está incorporada à concepção da lista.' },
    { t: 'A ausência de determinada doença na lista não impede o reconhecimento da relação com o trabalho quando demonstrada por evidência clínica e epidemiológica.', ok: false,
      why: 'Verdadeira. Há previsão expressa de reconhecimento de agravos não listados quando comprovada a relação.' },
    { t: 'A lista tem papel também na vigilância em saúde do trabalhador, orientando notificação e ações coletivas.', ok: false,
      why: 'Verdadeira. Além do uso clínico e pericial, a lista organiza a vigilância epidemiológica dos agravos relacionados ao trabalho.' }
  ],
  comentario: 'A lista relaciona agentes de risco ocupacionais às doenças correspondentes, incorpora a lógica de Schilling e orienta notificação e vigilância. É ferramenta de apoio: não substitui a avaliação da exposição individual nem esgota as possibilidades de reconhecimento.',
  pegadinha: 'Tratar a lista como presunção absoluta de nexo é o erro mais comum. Ela orienta e facilita, mas não dispensa demonstrar que aquele trabalhador esteve exposto ao agente.',
  refs: ['Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde', 'Portaria de atualização da lista'] },

{ id: 'q-4.1-015', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de frigorífico, 41 anos, oito anos na desossa, com dor em ombro direito e diagnóstico de síndrome do manguito rotador. Exame de imagem mostra também alterações degenerativas compatíveis com a idade. A empresa sustenta que "por haver degeneração, a doença não é ocupacional". Qual raciocínio de nexo é o correto?',
  alts: [
    { t: 'A coexistência de alterações degenerativas não exclui o nexo: cabe avaliar se as condições de trabalho, pela repetitividade, força e postura, contribuíram para o desencadeamento ou o agravamento do quadro, situação típica dos grupos de fator contributivo e de agravamento de Schilling.', ok: true,
      why: 'Correta. Achados degenerativos são frequentes em assintomáticos da mesma faixa etária; o que define o nexo é a contribuição das condições de trabalho ao adoecimento e à incapacidade.' },
    { t: 'A presença de degeneração enquadra o caso na exclusão legal de doença degenerativa, encerrando a discussão de nexo.', ok: false,
      why: 'Errada. A exclusão legal se refere a processos degenerativos sem relação com o trabalho; não é aplicável quando o trabalho contribui para o quadro.' },
    { t: 'O nexo só poderia ser reconhecido se a imagem fosse inteiramente normal, exceto pela lesão tendínea.', ok: false,
      why: 'Errada. Exigir imagem imaculada torna o reconhecimento impossível na prática e não corresponde ao raciocínio de causalidade.' },
    { t: 'O nexo depende exclusivamente de laudo de insalubridade favorável ao setor.', ok: false,
      why: 'Errada. Insalubridade é conceito de adicional remuneratório e de agentes específicos, e não é condição para caracterizar nexo em doença osteomuscular.' },
    { t: 'Como se trata de doença de alta prevalência na população geral, deve ser classificada obrigatoriamente como doença comum sem relação com o trabalho.', ok: false,
      why: 'Errada. Alta prevalência geral é justamente a marca das doenças em que o trabalho pode atuar como fator contributivo ou de agravamento.' }
  ],
  comentario: 'Alta prevalência populacional e achados degenerativos de imagem não afastam o nexo. O raciocínio busca contribuição do trabalho: exposição documentada, plausibilidade biológica, relação temporal, comportamento dos sintomas frente ao afastamento e comparação com grupos não expostos.',
  pegadinha: 'A palavra "degenerativa" na imagem é usada como se fosse a exclusão legal de doença degenerativa. São coisas diferentes.',
  refs: ['Lei 8.213/91', 'Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.1-016', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a diferença conceitual entre monitoramento biológico de exposição e monitoramento de efeito, aplicada à vigilância de trabalhadores expostos a agentes químicos, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O indicador biológico de exposição mede o agente ou seu metabólito em meio biológico, enquanto o indicador de efeito mede alteração bioquímica ou funcional precoce provocada pelo agente, e ambos servem à prevenção antes da doença instalada.', ok: true,
      why: 'Correta. A distinção é justamente entre quantificar a dose interna e detectar a repercussão biológica precoce, sempre com finalidade preventiva.' },
    { t: 'Indicadores de efeito são exames que confirmam o diagnóstico da doença já estabelecida, substituindo a avaliação clínica.', ok: false,
      why: 'Errada. O indicador de efeito busca alteração precoce, ainda subclínica; não é exame diagnóstico da doença instalada.' },
    { t: 'Resultado dentro do valor de referência para o indicador de exposição garante ausência de risco individual.', ok: false,
      why: 'Errada. Valores de referência são construídos em base populacional e não garantem ausência de efeito no indivíduo, especialmente para agentes sem limiar seguro.' },
    { t: 'O monitoramento biológico dispensa a avaliação ambiental, por ser mais sensível em todas as situações.', ok: false,
      why: 'Errada. Os dois se complementam: a avaliação ambiental orienta o controle na fonte, e a biológica capta a dose efetivamente absorvida por todas as vias.' },
    { t: 'A dosagem de indicadores biológicos deve ser sempre colhida no início da jornada de segunda-feira, independentemente da cinética do agente.', ok: false,
      why: 'Errada. O momento da coleta depende da meia-vida e da cinética de cada agente, variando entre fim de jornada, fim de semana de trabalho ou pré-jornada.' }
  ],
  comentario: 'Exposição: agente ou metabólito no organismo. Efeito: alteração biológica precoce induzida pelo agente. O momento da coleta é determinado pela cinética do agente. Monitoramento biológico e ambiental são complementares, nunca excludentes.',
  pegadinha: 'Interpretar "resultado dentro do valor de referência" como "sem risco" é o erro conceitual que a questão persegue. Referência é parâmetro populacional, não certificado individual de segurança.',
  refs: ['Mendes, R. — Patologia do Trabalho', 'NR-7 — monitoramento biológico'] },

{ id: 'q-4.1-017', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um serviço de saúde do trabalhador identifica, em uma mesma empresa de galvanoplastia, quatro casos de dermatose de mãos em seis meses entre doze trabalhadores do mesmo setor. Qual é a leitura epidemiológica correta desse achado para fins de patologia do trabalho?',
  alts: [
    { t: 'A concentração de casos semelhantes em trabalhadores que compartilham o mesmo processo e a mesma exposição é forte indício de origem ocupacional e indica investigação coletiva do posto de trabalho, não apenas conduta individual.', ok: true,
      why: 'Correta. Agrupamento de casos com exposição comum é um dos critérios epidemiológicos clássicos de suspeita de nexo e desloca a abordagem do indivíduo para o ambiente.' },
    { t: 'O número absoluto é pequeno demais para qualquer inferência, devendo cada caso ser tratado isoladamente como dermatose comum.', ok: false,
      why: 'Errada. Em populações pequenas, a proporção de acometidos é que importa; quatro casos em doze expostos é uma taxa de ataque expressiva.' },
    { t: 'Somente estudos com grupo controle externo permitem qualquer suspeita de origem ocupacional.', ok: false,
      why: 'Errada. A suspeita se levanta com a observação clínica e a exposição compartilhada; estudos formais podem vir depois, mas não são pré-requisito para agir.' },
    { t: 'A investigação deve começar pela pesquisa de atopia individual, uma vez que a suscetibilidade explica agrupamentos de casos.', ok: false,
      why: 'Errada. Suscetibilidade individual não explica agrupamento em torno de um processo específico; começar pelo indivíduo desvia da causa comum.' },
    { t: 'Havendo uso de equipamento de proteção individual fornecido, fica descartada a origem ocupacional.', ok: false,
      why: 'Errada. Fornecimento de proteção não comprova adequação, uso correto nem eficácia; o adoecimento em série sugere justamente falha do controle.' }
  ],
  comentario: 'Critérios epidemiológicos de suspeita ocupacional: agrupamento de casos com exposição comum, relação temporal com o trabalho, melhora no afastamento, gradiente dose-resposta e comparação com não expostos. Cluster em setor pequeno pede vigilância no ambiente.',
  pegadinha: 'A resposta que atribui o agrupamento à suscetibilidade individual (atopia) é sedutora em dermatoses e é justamente o mecanismo de individualização do risco que a vigilância deve evitar.',
  refs: ['Vigilância em Saúde do Trabalhador — Ministério da Saúde', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-018', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Motorista de caminhão, 47 anos, apresenta lombalgia crônica com hérnia discal L4-L5. Trabalha há 18 anos em veículo com assento sem suspensão adequada, cumprindo jornadas prolongadas e realizando também carga e descarga manual. Quanto ao enquadramento segundo a lógica de Schilling e à conduta:',
  alts: [
    { t: 'Trata-se tipicamente de doença em que o trabalho atua como fator de risco contributivo entre outros, e a conduta deve incluir avaliação ergonômica do posto, e não apenas tratamento clínico e afastamento.', ok: true,
      why: 'Correta. Vibração de corpo inteiro, postura sentada prolongada e manuseio de carga são fatores contributivos reconhecidos; a intervenção precisa alcançar as condições de trabalho.' },
    { t: 'É doença com o trabalho como causa necessária, pois hérnia discal não ocorre fora de contexto ocupacional.', ok: false,
      why: 'Errada. Hérnia discal é frequente na população geral e não depende de exposição ocupacional para existir.' },
    { t: 'Trata-se de doença exclusivamente degenerativa e, por isso, sem qualquer relação com o trabalho.', ok: false,
      why: 'Errada. A degeneração discal é ubíqua, mas o trabalho pode acelerar e agravar o processo e precipitar a incapacidade.' },
    { t: 'A conduta indicada é o repouso absoluto prolongado até a resolução completa da dor.', ok: false,
      why: 'Errada. O repouso prolongado piora o prognóstico funcional; a orientação atual é manutenção de atividade tolerável e retorno progressivo.' },
    { t: 'A confirmação por ressonância de hérnia discal é suficiente para caracterizar incapacidade laborativa total e permanente.', ok: false,
      why: 'Errada. Achados de imagem existem em grande proporção de assintomáticos; a incapacidade se avalia pela clínica e pela demanda funcional do posto.' }
  ],
  comentario: 'Lombalgia e discopatia em motoristas ilustram o grupo de fator contributivo: vibração de corpo inteiro, postura sentada prolongada e manuseio de carga somam-se a fatores individuais. Conduta é dupla — clínica e ergonômica —, com repouso prolongado contraindicado.',
  pegadinha: 'A dissociação clínico-radiológica na coluna é regra: imagem alterada em assintomáticos e imagem pobre em sintomáticos graves. Diagnóstico de incapacidade não se faz pela ressonância.',
  refs: ['Protocolo de Dorsalgias Relacionadas ao Trabalho — Ministério da Saúde', 'Schilling, R.S.F.'] },

{ id: 'q-4.1-019', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre o conceito de suscetibilidade individual e sua utilização em patologia do trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'Constatada suscetibilidade individual aumentada, a conduta preferencial é a seleção de trabalhadores por exame prévio, excluindo os suscetíveis da atividade em lugar de controlar a exposição.', ok: true,
      why: 'É a afirmação FALSA e portanto a resposta. A hierarquia de controle exige atuar sobre o risco; a exclusão de suscetíveis transfere ao trabalhador o ônus do risco e não protege os demais expostos.' },
    { t: 'Fatores individuais como atopia, polimorfismos metabólicos e comorbidades podem modular a resposta a um mesmo nível de exposição.', ok: false,
      why: 'Verdadeira. A variabilidade biológica na resposta a exposições é bem documentada.' },
    { t: 'Limites de exposição são construídos para proteger a maioria dos trabalhadores, não necessariamente todos os indivíduos.', ok: false,
      why: 'Verdadeira. Essa ressalva consta das próprias metodologias de definição de limites.' },
    { t: 'O uso de informação genética para seleção de trabalhadores levanta objeções éticas relevantes, entre elas o risco de discriminação.', ok: false,
      why: 'Verdadeira. É preocupação ética central no debate sobre triagem genética ocupacional.' },
    { t: 'A identificação de trabalhadores mais suscetíveis pode justificar monitoramento diferenciado, desde que mantidas as medidas coletivas de controle.', ok: false,
      why: 'Verdadeira. Vigilância reforçada é legítima quando não substitui o controle na fonte.' }
  ],
  comentario: 'Suscetibilidade individual existe e justifica vigilância, mas nunca substitui o controle do risco. Selecionar "os resistentes" é estratégia rejeitada em saúde do trabalhador: não reduz a exposição, discrimina e deixa desprotegidos os que permanecem.',
  pegadinha: 'A frase soa razoável — "afastar quem é mais sensível" —, mas inverte a hierarquia de controle e é eticamente rejeitada.',
  refs: ['Ética em Saúde do Trabalhador', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-020', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Uma trabalhadora de lavanderia industrial apresenta quadro respiratório recorrente. Ao aplicar critérios de causalidade para decidir sobre o nexo ocupacional, o médico do trabalho deve considerar que:',
  alts: [
    { t: 'O raciocínio de nexo combina exposição documentada e suficiente, plausibilidade biológica, coerência temporal entre exposição e quadro, comportamento dos sintomas frente ao afastamento e exclusão razoável de outras causas.', ok: true,
      why: 'Correta. Esse conjunto reproduz os critérios de causalidade aplicados ao caso individual em medicina do trabalho.' },
    { t: 'A demonstração de associação estatística em estudos populacionais é condição suficiente para afirmar o nexo individual.', ok: false,
      why: 'Errada. Evidência epidemiológica sustenta a plausibilidade, mas o nexo individual exige demonstrar exposição e coerência no caso concreto.' },
    { t: 'Para haver nexo é indispensável que a doença seja exclusiva de trabalhadores expostos.', ok: false,
      why: 'Errada. Exclusividade caracteriza apenas as doenças de causa necessária; a maioria dos agravos relacionados ao trabalho também ocorre na população geral.' },
    { t: 'Se o trabalhador apresenta hábito de risco pessoal, como tabagismo, o nexo ocupacional fica automaticamente excluído.', ok: false,
      why: 'Errada. Fatores pessoais podem coexistir e até interagir com o agente ocupacional, sem excluir a contribuição do trabalho.' },
    { t: 'A ausência de laudo pericial judicial impede o médico assistente de concluir por nexo ocupacional.', ok: false,
      why: 'Errada. O médico assistente pode e deve estabelecer sua conclusão diagnóstica e emitir os documentos correspondentes, independentemente de perícia.' }
  ],
  comentario: 'Nexo individual não se resolve com um único critério. Exige exposição real e suficiente, plausibilidade, temporalidade compatível, comportamento clínico consistente com o afastamento e afastamento razoável de causas alternativas. Fatores pessoais somam-se, não excluem.',
  pegadinha: 'A ideia de que o tabagismo "anula" o nexo é usada com frequência para negar reconhecimento — e é justamente em exposições como asbesto que a interação com o tabaco potencializa o risco.',
  refs: ['Critérios de causalidade aplicados à saúde do trabalhador', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-021', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de marmoraria apresenta silicose confirmada. Sobre a caracterização desse agravo em patologia do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'É doença em que o trabalho é causa necessária, de notificação compulsória, sem tratamento específico e que pode progredir mesmo após o afastamento da exposição, o que não afasta a indicação de cessar a exposição.', ok: true,
      why: 'Correta. A exposição à sílica é indispensável para a doença, a notificação é obrigatória, não há terapêutica que reverta a fibrose e a progressão pós-exposição é conhecida — o que torna o afastamento medida de contenção, não de cura.' },
    { t: 'Por ser irreversível e progredir após o afastamento, a remoção da exposição perdeu sentido clínico.', ok: false,
      why: 'Errada. Cessar a exposição reduz a carga acumulada e a velocidade de progressão, além de prevenir formas mais graves.' },
    { t: 'Trata-se de doença do trabalho na acepção estrita, pois decorre de condições especiais e não do exercício peculiar da atividade.', ok: false,
      why: 'Errada. A silicose é o exemplo clássico de doença profissional, ligada ao exercício de atividades com exposição a sílica.' },
    { t: 'A confirmação diagnóstica exige biópsia pulmonar em todos os casos.', ok: false,
      why: 'Errada. História ocupacional consistente somada a quadro radiológico compatível costuma bastar; a biópsia fica para casos atípicos.' },
    { t: 'A doença não integra a relação de agravos de notificação, por não ser transmissível.', ok: false,
      why: 'Errada. A notificação compulsória em saúde do trabalhador abrange agravos não transmissíveis, incluindo as pneumoconioses.' }
  ],
  comentario: 'Silicose reúne, em uma só doença, quase tudo o que a banca cobra em patologia do trabalho: causa necessária, irreversibilidade, progressão pós-exposição, diagnóstico clínico-ocupacional-radiológico, notificação compulsória e complicação por tuberculose.',
  pegadinha: 'A dedução "se progride mesmo afastado, então afastar não adianta" é falsa. Reduzir a carga de sílica retida e evitar novas cargas continua sendo a única medida efetiva.',
  refs: ['Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde', 'Santos, U.P. — Pneumologia Ocupacional'] },

{ id: 'q-4.1-022', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a diferença entre doença relacionada ao trabalho e acidente do trabalho típico, no contexto da patologia do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O acidente típico se caracteriza pelo evento súbito e datável, ao passo que a doença relacionada ao trabalho decorre de exposição habitualmente prolongada, embora ambos gerem os mesmos efeitos legais acidentários.', ok: true,
      why: 'Correta. A diferença é de temporalidade do agente lesivo, e não de consequência jurídica, já que as doenças ocupacionais se equiparam a acidente do trabalho.' },
    { t: 'Somente o acidente típico enseja emissão de comunicação de acidente do trabalho.', ok: false,
      why: 'Errada. A comunicação também é devida nas doenças relacionadas ao trabalho.' },
    { t: 'Doença relacionada ao trabalho nunca pode decorrer de exposição única.', ok: false,
      why: 'Errada. Exposição única e maciça pode produzir agravo, como na síndrome de disfunção reativa das vias aéreas após inalação de irritante.' },
    { t: 'A estabilidade acidentária é exclusiva dos casos de acidente típico.', ok: false,
      why: 'Errada. A equiparação legal estende às doenças ocupacionais as mesmas repercussões, inclusive a estabilidade quando presentes seus requisitos.' },
    { t: 'A distinção entre acidente e doença é irrelevante, pois o tratamento clínico é o mesmo.', ok: false,
      why: 'Errada. A distinção orienta investigação, vigilância, medidas preventivas e a própria caracterização documental do caso.' }
  ],
  comentario: 'Acidente típico: evento súbito, datável, com lesão imediata. Doença ocupacional: instalação gradual por exposição continuada, com equiparação legal a acidente do trabalho. Ambos geram comunicação e repercussões acidentárias.',
  pegadinha: 'A exposição aguda única que produz doença crônica quebra a regra do "gradual sempre" e é usada para derrubar quem memorizou a definição de forma rígida.',
  refs: ['Lei 8.213/91', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-023', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Ao avaliar trabalhador com quadro neurológico e história de exposição a solventes, o médico do trabalho verifica que os sintomas melhoram nas férias e retornam poucas semanas após o retorno. Como esse dado deve ser interpretado no raciocínio de nexo?',
  alts: [
    { t: 'A melhora no afastamento e a recidiva no retorno constituem critério temporal favorável ao nexo, mas devem ser interpretados com cautela, pois nem todo agravo ocupacional regride com o afastamento e alguns podem melhorar por razões inespecíficas.', ok: true,
      why: 'Correta. O padrão é um critério robusto de suspeita, com duas ressalvas conhecidas: agravos irreversíveis não regridem, e o alívio pode refletir apenas o descanso.' },
    { t: 'A melhora nas férias prova de forma definitiva a origem ocupacional, dispensando outros critérios.', ok: false,
      why: 'Errada. Nenhum critério isolado prova nexo; o afastamento também remove estresse, sono irregular e esforço físico.' },
    { t: 'Se o quadro não regride com o afastamento, o nexo ocupacional está necessariamente excluído.', ok: false,
      why: 'Errada. Silicose, asbestose, perda auditiva induzida por ruído e neuropatias tóxicas estabelecidas não regridem, e nem por isso deixam de ser ocupacionais.' },
    { t: 'A observação de melhora só tem valor se documentada por exame complementar realizado no mesmo dia do retorno.', ok: false,
      why: 'Errada. O registro clínico sequencial é o instrumento adequado; não há exigência de exame pontual.' },
    { t: 'A recidiva no retorno deve ser atribuída a simulação sempre que os exames complementares forem normais.', ok: false,
      why: 'Errada. Exames normais não autorizam presunção de simulação; muitos agravos ocupacionais precoces cursam com exames inalterados.' }
  ],
  comentario: 'Melhora no afastamento e piora no retorno é critério temporal clássico de suspeita ocupacional — bem estabelecido em asma ocupacional e dermatoses. Tem dois limites: não se aplica a agravos irreversíveis e não é prova isolada de causalidade.',
  pegadinha: 'A questão testa os dois extremos: quem transforma o critério em prova absoluta e quem o usa às avessas para excluir doenças irreversíveis.',
  refs: ['Mendes, R. — Patologia do Trabalho', 'Critérios de nexo em doenças ocupacionais'] },

{ id: 'q-4.1-024', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Em uma indústria química, o serviço médico identifica que trabalhadores com maior tempo e intensidade de exposição a determinado agente apresentam maior frequência e maior gravidade de um mesmo sinal clínico. Do ponto de vista de patologia do trabalho, esse achado corresponde a:',
  alts: [
    { t: 'Gradiente dose-resposta, um dos critérios que mais reforçam a hipótese de causalidade ocupacional, e que orienta priorizar o controle nos postos de maior exposição.', ok: true,
      why: 'Correta. A relação entre magnitude da exposição e magnitude do efeito é um dos critérios de causalidade mais valorizados e tem aplicação prática direta na priorização do controle.' },
    { t: 'Viés de seleção do trabalhador sadio, que explica integralmente o achado.', ok: false,
      why: 'Errada. Esse viés tende a subestimar efeitos, produzindo menos doença entre trabalhadores, e não um gradiente crescente com a exposição.' },
    { t: 'Fenômeno de tolerância, esperado quando a exposição é prolongada.', ok: false,
      why: 'Errada. Tolerância implicaria atenuação dos efeitos com o tempo de exposição, o oposto do descrito.' },
    { t: 'Achado sem valor causal, por se tratar de observação em população pequena.', ok: false,
      why: 'Errada. O gradiente é informativo mesmo em amostras modestas e serve para gerar hipótese e ação preventiva imediata.' },
    { t: 'Efeito de causalidade reversa, em que a doença determina a exposição.', ok: false,
      why: 'Errada. Nada no cenário sugere que o adoecimento tenha determinado a alocação em postos mais expostos.' }
  ],
  comentario: 'Gradiente dose-resposta: quanto maior a exposição, maior a frequência ou gravidade do efeito. É um dos critérios de causalidade mais fortes e, na prática, aponta onde intervir primeiro. Sua ausência não exclui nexo, sobretudo em agentes sensibilizantes e carcinógenos sem limiar.',
  pegadinha: 'O efeito do trabalhador sadio é distrator recorrente porque também vem da epidemiologia ocupacional, mas atua no sentido inverso: mascara efeitos em vez de criar gradientes.',
  refs: ['Epidemiologia Ocupacional', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-025', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Cozinheira de restaurante industrial, 38 anos, apresenta quadro compatível com dermatite crônica de mãos. Ela também é diarista aos fins de semana e tem antecedente de dermatite atópica na infância. Sobre a análise do nexo neste caso, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A presença de exposição extralaboral e de atopia prévia não exclui o nexo, mas obriga a caracterizar a magnitude relativa das exposições e o comportamento clínico do quadro em relação à jornada de trabalho.', ok: true,
      why: 'Correta. Concausas não anulam o nexo; exigem que se demonstre a contribuição relevante da exposição ocupacional e o padrão temporal do quadro.' },
    { t: 'A existência de atopia enquadra o caso como doença comum, encerrando a investigação ocupacional.', ok: false,
      why: 'Errada. Atopia é fator de suscetibilidade e frequentemente coexiste com dermatose ocupacional, ampliando o risco em vez de excluí-lo.' },
    { t: 'Como há trabalho doméstico remunerado nos fins de semana, a exposição ocupacional principal deve ser desconsiderada.', ok: false,
      why: 'Errada. A segunda atividade também é trabalho e deve entrar na análise; nada autoriza descartar a exposição do vínculo formal.' },
    { t: 'A concausa é conceito estranho à medicina do trabalho e não tem repercussão no reconhecimento do agravo.', ok: false,
      why: 'Errada. A concausa é reconhecida: basta que o trabalho tenha contribuído de forma relevante para o resultado.' },
    { t: 'Só haveria nexo se a trabalhadora não tivesse qualquer outra fonte de exposição a irritantes.', ok: false,
      why: 'Errada. Exigir exposição ocupacional exclusiva inviabiliza o reconhecimento em praticamente todas as dermatoses.' }
  ],
  comentario: 'Concausa: o trabalho não precisa ser a única causa, basta contribuir de modo relevante para o resultado. Atopia e exposições extralaborais são fatores a caracterizar e ponderar, não motivos automáticos de exclusão.',
  pegadinha: 'O trabalho doméstico remunerado é usado no enunciado como falsa saída — é trabalho, também expõe, e não serve para excluir o vínculo principal.',
  refs: ['Salim — Dermatoses Ocupacionais', 'Conceito de concausa — Lei 8.213/91'] },

{ id: 'q-4.1-026', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Assinale a alternativa que apresenta corretamente exemplos de agravos classificados, respectivamente, como doença em que o trabalho é causa necessária, doença em que o trabalho é fator de risco contributivo e doença comum agravada pelo trabalho:',
  alts: [
    { t: 'Saturnismo; doença isquêmica do coração em trabalhador exposto a estresse ocupacional; varizes de membros inferiores em trabalhador que permanece longos períodos em pé.', ok: true,
      why: 'Correta. A intoxicação por chumbo exige exposição ocupacional; a doença isquêmica reconhece o trabalho como um entre vários fatores; e a doença varicosa é de alta prevalência geral, cujo curso pode ser agravado pela permanência prolongada em ortostatismo.' },
    { t: 'Mesotelioma; silicose; asbestose.', ok: false,
      why: 'Errada. Os três são exemplos de agravos com o trabalho como causa necessária, não representando os três grupos distintos.' },
    { t: 'Hipertensão arterial; perda auditiva induzida por ruído; berilose.', ok: false,
      why: 'Errada. A ordem não corresponde: perda auditiva induzida por ruído e beriliose são de causa necessária, e a hipertensão não é.' },
    { t: 'Lombalgia inespecífica; dermatite de contato irritativa; intoxicação por benzeno.', ok: false,
      why: 'Errada. A sequência está invertida quanto ao primeiro e ao último termos, já que a intoxicação por benzeno é o exemplo de causa necessária.' },
    { t: 'Tuberculose em profissional de saúde; asma agravada pelo trabalho; câncer de pulmão em trabalhador exposto a asbesto e tabagista.', ok: false,
      why: 'Errada quanto à ordem: o segundo termo é agravamento e o terceiro é fator contributivo, invertendo a sequência pedida.' }
  ],
  comentario: 'Exemplos-âncora para memorizar Schilling: causa necessária (silicose, asbestose, mesotelioma, saturnismo, benzenismo, perda auditiva induzida por ruído); fator contributivo (doença isquêmica, hipertensão, alguns cânceres); agravamento (varizes, asma preexistente, transtornos mentais comuns).',
  pegadinha: 'Vários distratores trazem exemplos corretos em ordem errada. A prova exige a correspondência posicional, não só o reconhecimento dos exemplos.',
  refs: ['Schilling, R.S.F.', 'Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde'] },

{ id: 'q-4.1-027', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Durante consulta, um trabalhador relata sintomas que atribui a produto químico que manuseia, mas desconhece o nome da substância. Qual conduta é a mais adequada do ponto de vista da anamnese ocupacional e da investigação do agravo?',
  alts: [
    { t: 'Solicitar a ficha de informações de segurança de produtos químicos e a descrição do processo, além de inspecionar ou requisitar dados do posto de trabalho, pois a identificação do agente é etapa indispensável do raciocínio diagnóstico.', ok: true,
      why: 'Correta. Sem identificar o agente não se avalia toxicidade, via de absorção, indicadores biológicos aplicáveis nem medida de controle; a documentação do produto e a análise do processo são as fontes adequadas.' },
    { t: 'Registrar apenas "exposição a produto químico não identificado" e encerrar a investigação, por ausência de dados.', ok: false,
      why: 'Errada. O desconhecimento do trabalhador é a razão para buscar a informação, e não para encerrar a apuração.' },
    { t: 'Solicitar painel amplo de dosagens toxicológicas séricas, sem definir o agente, para rastrear qualquer intoxicação.', ok: false,
      why: 'Errada. Não existe painel universal útil; a escolha do indicador biológico depende do agente e da sua cinética.' },
    { t: 'Presumir que produtos de uso industrial disponíveis no mercado são seguros quando fornecidos com equipamento de proteção.', ok: false,
      why: 'Errada. Disponibilidade comercial e fornecimento de proteção não presumem segurança nem eficácia do controle.' },
    { t: 'Encaminhar o caso à perícia previdenciária antes de qualquer caracterização da exposição.', ok: false,
      why: 'Errada. A caracterização da exposição é atribuição da assistência e da vigilância; encaminhar sem investigar transfere a lacuna adiante.' }
  ],
  comentario: 'Identificar o agente é passo obrigatório: define toxicidade, órgão-alvo, via de absorção, indicador biológico pertinente, latência esperada e medida de controle. Ficha de informações de segurança, inventário de produtos e análise do processo são as fontes.',
  pegadinha: 'A ideia de "rastrear tudo" com um painel toxicológico amplo é atraente e clinicamente inútil: cada agente tem indicador, matriz e momento de coleta próprios.',
  refs: ['Ficha de Informações de Segurança de Produtos Químicos', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-028', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um trabalhador com quadro respiratório é avaliado por médico assistente que não é especialista em medicina do trabalho e que registra no prontuário apenas o diagnóstico clínico, sem qualquer menção à ocupação. Do ponto de vista de patologia do trabalho, qual é a consequência mais relevante dessa omissão?',
  alts: [
    { t: 'A subnotificação e a invisibilidade epidemiológica dos agravos relacionados ao trabalho, com perda da oportunidade de intervir sobre a exposição de todos os demais trabalhadores do mesmo posto.', ok: true,
      why: 'Correta. O caso não reconhecido deixa de gerar notificação, investigação e ação coletiva, perpetuando a exposição para os companheiros de trabalho.' },
    { t: 'Nenhuma, uma vez que o tratamento clínico prescrito seria o mesmo com ou sem a identificação do nexo.', ok: false,
      why: 'Errada. Mesmo quando o tratamento sintomático coincide, o afastamento da exposição é parte do tratamento e só ocorre se o nexo for reconhecido.' },
    { t: 'Apenas perda de direito previdenciário do trabalhador, sem repercussão coletiva.', ok: false,
      why: 'Errada. A repercussão individual existe, mas a consequência mais ampla é a perda da ação sobre o ambiente.' },
    { t: 'A impossibilidade definitiva de reconhecimento posterior do nexo.', ok: false,
      why: 'Errada. O reconhecimento pode ocorrer depois, ainda que dificultado pela ausência de registro contemporâneo.' },
    { t: 'A invalidação automática de todo o prontuário para fins periciais.', ok: false,
      why: 'Errada. O prontuário permanece válido; o que falta é a informação ocupacional, que pode ser complementada.' }
  ],
  comentario: 'A subnotificação é o maior problema epidemiológico da área. Um caso reconhecido é um caso-sentinela: aponta falha de controle e desencadeia investigação de todo o coletivo exposto. Sem a pergunta sobre a ocupação, o agravo desaparece das estatísticas e a exposição continua.',
  pegadinha: 'A alternativa que limita o prejuízo ao plano individual é parcialmente verdadeira e por isso engana. A perda maior é coletiva e preventiva.',
  refs: ['Vigilância em Saúde do Trabalhador — Ministério da Saúde', 'Conceito de evento-sentinela'] },

{ id: 'q-4.1-029', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre o conceito de evento-sentinela em saúde do trabalhador, assinale a alternativa CORRETA:',
  alts: [
    { t: 'É a ocorrência de doença, incapacidade ou morte cuja existência serve como sinal de alerta de que a qualidade preventiva pode estar comprometida, exigindo investigação do ambiente de trabalho.', ok: true,
      why: 'Correta. O evento-sentinela é usado como indicador de falha do sistema de prevenção, e sua identificação obriga a investigar o coletivo exposto.' },
    { t: 'É todo agravo que atinge simultaneamente mais de dez trabalhadores do mesmo setor.', ok: false,
      why: 'Errada. Não há critério numérico: um único caso já é suficiente para funcionar como sentinela.' },
    { t: 'É sinônimo de acidente do trabalho grave com afastamento superior a quinze dias.', ok: false,
      why: 'Errada. Gravidade e duração do afastamento não definem o conceito, que se apoia na função de alerta do caso.' },
    { t: 'Aplica-se somente a doenças infecciosas de notificação compulsória.', ok: false,
      why: 'Errada. O conceito abrange agravos não transmissíveis, incluindo pneumoconioses, intoxicações e perdas auditivas.' },
    { t: 'É evento cuja investigação compete exclusivamente ao empregador, sem participação do serviço público de vigilância.', ok: false,
      why: 'Errada. A vigilância em saúde do trabalhador tem atribuição de investigar, com participação dos serviços públicos.' }
  ],
  comentario: 'Evento-sentinela: um caso que sinaliza falha preventiva. Um único silicótico, um único caso de benzenismo ou uma única perda auditiva confirmada bastam para desencadear investigação de todo o grupo exposto. O conceito desloca o foco do indivíduo para o sistema.',
  pegadinha: 'Distratores tentam impor critérios quantitativos ou de gravidade. O conceito é qualitativo: importa a capacidade de sinalizar falha, não o número de acometidos.',
  refs: ['Rutstein — eventos-sentinela', 'Vigilância em Saúde do Trabalhador — Ministério da Saúde'] },

{ id: 'q-4.1-030', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de baterias, 44 anos, apresenta cólica abdominal, anemia e história de exposição a chumbo. O médico do trabalho, ao caracterizar o agravo, considera que a intoxicação por chumbo é doença em que o trabalho é causa necessária. Sobre esse enquadramento e suas consequências práticas, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'Como a doença é de causa necessária, o afastamento do trabalhador é suficiente como medida, dispensando avaliação dos demais expostos do mesmo setor.', ok: true,
      why: 'É a afirmação FALSA e portanto a resposta. Um caso confirmado é evento-sentinela e obriga a avaliar todo o grupo exposto e a corrigir o processo.' },
    { t: 'O caso deve ser notificado e comunicado como agravo relacionado ao trabalho.', ok: false,
      why: 'Verdadeira. Intoxicação exógena de origem ocupacional integra os agravos de notificação e enseja comunicação de acidente do trabalho.' },
    { t: 'O afastamento da exposição é parte do tratamento, e não apenas medida administrativa.', ok: false,
      why: 'Verdadeira. Interromper a absorção é conduta terapêutica essencial em intoxicações crônicas.' },
    { t: 'A dosagem de indicador biológico auxilia a caracterizar a exposição, mas não substitui a avaliação clínica.', ok: false,
      why: 'Verdadeira. Indicadores biológicos e clínica são complementares na caracterização do quadro.' },
    { t: 'A ausência de exposição ocupacional a chumbo obrigaria a investigar fontes ambientais ou domiciliares antes de firmar o nexo com o trabalho.', ok: false,
      why: 'Verdadeira. Existem fontes não ocupacionais e sua investigação é parte do raciocínio diagnóstico.' }
  ],
  comentario: 'Caso confirmado de intoxicação ocupacional obriga sempre a duas frentes: cuidado individual, com afastamento da exposição como parte do tratamento, e investigação coletiva do grupo exposto, com correção do processo produtivo.',
  pegadinha: 'A afirmação falsa é atraente porque a conduta individual descrita está correta; o erro está no que ela dispensa — a avaliação dos demais expostos.',
  refs: ['Protocolo de Intoxicação por Chumbo — Ministério da Saúde', 'NR-7'] },

{ id: 'q-4.1-031', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre o Nexo Técnico Epidemiológico Previdenciário e sua relação com o raciocínio clínico de patologia do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de mecanismo que presume a relação entre o agravo e o trabalho a partir da associação estatística entre a atividade econômica do empregador e o diagnóstico, admitindo contestação, e não substitui a avaliação clínica individual do nexo.', ok: true,
      why: 'Correta. É presunção de base epidemiológica, passível de afastamento mediante demonstração em contrário, e não elimina o exame clínico do caso.' },
    { t: 'Uma vez aplicado, torna definitivo e incontestável o reconhecimento do nexo.', ok: false,
      why: 'Errada. Há previsão de contestação por parte da empresa, com análise específica.' },
    { t: 'Aplica-se apenas a acidentes típicos com lesão imediata.', ok: false,
      why: 'Errada. Sua lógica é justamente a das doenças associadas estatisticamente à atividade econômica.' },
    { t: 'Sua aplicação depende de laudo pericial judicial prévio.', ok: false,
      why: 'Errada. A aplicação ocorre no âmbito administrativo da concessão do benefício.' },
    { t: 'Sua existência dispensa o médico assistente de registrar a história ocupacional.', ok: false,
      why: 'Errada. O registro clínico da exposição continua sendo elemento essencial da avaliação e da defesa do trabalhador.' }
  ],
  comentario: 'O nexo epidemiológico presume relação entre diagnóstico e atividade econômica com base em associação estatística. É presunção relativa, admite contestação e não dispensa o raciocínio clínico individual nem o registro da história ocupacional.',
  pegadinha: 'Tratar a presunção como prova absoluta é o erro. Ela inverte o ônus da demonstração, mas não encerra a discussão clínica.',
  refs: ['Nexo Técnico Epidemiológico Previdenciário', 'Lei 8.213/91'] },

{ id: 'q-4.1-032', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Em serviço de referência, chega trabalhador rural com quadro neurológico agudo após aplicação de agrotóxico. Sobre o raciocínio de patologia do trabalho aplicado às intoxicações agudas, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A intoxicação aguda é agravo de instalação súbita relacionado ao trabalho, deve ser notificada, e a identificação do grupo químico do produto orienta tanto o tratamento específico quanto as medidas de proteção dos demais trabalhadores.', ok: true,
      why: 'Correta. Definir o grupo químico é o que permite antídoto ou manejo específico, além de direcionar a intervenção no processo de trabalho e a proteção do coletivo.' },
    { t: 'Por ser evento agudo, deve ser tratado exclusivamente como acidente do trabalho, sem qualquer investigação do processo produtivo.', ok: false,
      why: 'Errada. A caracterização como acidente não dispensa a investigação das condições que permitiram a exposição.' },
    { t: 'O tratamento independe da identificação do produto, sendo sempre sintomático.', ok: false,
      why: 'Errada. Há condutas específicas conforme o grupo químico, e a identificação muda o desfecho.' },
    { t: 'A ausência de sintomas nos demais aplicadores exclui a necessidade de avaliação do grupo.', ok: false,
      why: 'Errada. Trabalhadores assintomáticos podem estar expostos e em fase inicial; a avaliação do grupo é parte da resposta ao caso.' },
    { t: 'Intoxicações agudas por agrotóxicos não integram os agravos de notificação em saúde do trabalhador.', ok: false,
      why: 'Errada. Intoxicação exógena está entre os agravos de notificação.' }
  ],
  comentario: 'Intoxicação aguda ocupacional: agravo súbito, notificável, com manejo dependente da identificação do grupo químico e com investigação obrigatória do processo de trabalho e do coletivo exposto, ainda que os demais estejam assintomáticos.',
  pegadinha: 'A dicotomia "é acidente, logo não se investiga exposição" é falsa. Evento agudo relacionado a agente químico exige as duas leituras.',
  refs: ['Protocolo de Intoxicação por Agrotóxicos — Ministério da Saúde', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-4.1-033', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre o efeito do trabalhador sadio na interpretação de dados de saúde ocupacional, assinale a alternativa CORRETA:',
  alts: [
    { t: 'É o viés pelo qual a população trabalhadora tende a apresentar indicadores de saúde melhores que a população geral, o que pode subestimar o efeito de exposições ocupacionais em estudos comparativos.', ok: true,
      why: 'Correta. Seleção para o emprego e permanência dos mais aptos produzem comparação desfavorável à detecção de efeitos quando o referencial é a população geral.' },
    { t: 'É o fenômeno pelo qual trabalhadores expostos adoecem mais que a população geral, superestimando o risco.', ok: false,
      why: 'Errada. O viés atua no sentido oposto, mascarando efeitos.' },
    { t: 'Ocorre apenas em estudos de coorte prospectivos.', ok: false,
      why: 'Errada. Manifesta-se em diferentes desenhos, sempre que a comparação envolve população trabalhadora e população geral.' },
    { t: 'É eliminado automaticamente quando se utiliza grupo controle formado por trabalhadores de outro setor da mesma empresa.', ok: false,
      why: 'Errada. O uso de controles internos atenua o problema, mas não o elimina automaticamente, pois pode haver seleção também entre setores.' },
    { t: 'Justifica concluir que exposições ocupacionais são pouco relevantes para a saúde pública.', ok: false,
      why: 'Errada. A conclusão é inversa: o viés indica que efeitos reais podem estar sendo subestimados.' }
  ],
  comentario: 'Efeito do trabalhador sadio: quem trabalha é, em média, mais saudável que a população geral por seleção de entrada e de permanência. Consequência prática: risco relativo próximo de um pode estar mascarando efeito real. Controles internos atenuam, mas não anulam.',
  pegadinha: 'Inverter a direção do viés é o erro mais comum, e a alternativa que o descreve como superestimação é escrita exatamente para isso.',
  refs: ['Epidemiologia Ocupacional', 'Mendes, R. — Patologia do Trabalho'] },

{ id: 'q-4.1-034', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Auxiliar de produção com quadro compatível com asma de início recente, sem antecedente respiratório, trabalhando há dois anos com resinas em marcenaria. Considerando os períodos de indução e latência aplicados às doenças alérgicas ocupacionais, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Em doenças de mecanismo alérgico ocupacional existe um período de sensibilização, variável de semanas a anos, após o qual mesmo exposições baixas passam a desencadear sintomas, o que explica quadro que surge depois de tempo assintomático de trabalho.', ok: true,
      why: 'Correta. Após a sensibilização, a resposta deixa de depender da dose que a produziu, e níveis previamente tolerados passam a desencadear crises.' },
    { t: 'A ausência de sintomas no primeiro ano de exposição exclui o mecanismo alérgico ocupacional.', ok: false,
      why: 'Errada. O período assintomático de sensibilização é justamente característico desse mecanismo.' },
    { t: 'Após instalada a sensibilização, os sintomas passam a depender estritamente da dose, cessando com reduções mínimas da concentração.', ok: false,
      why: 'Errada. O sensibilizado pode reagir a concentrações muito baixas, o que limita a eficácia de medidas apenas de redução.' },
    { t: 'Doenças alérgicas ocupacionais não apresentam período de indução, por serem de instalação imediata.', ok: false,
      why: 'Errada. A instalação imediata caracteriza reações irritativas ou tóxicas, não os quadros mediados por sensibilização.' },
    { t: 'A conduta correta é reduzir a jornada de exposição pela metade, mantendo o trabalhador na mesma função.', ok: false,
      why: 'Errada. Para agente sensibilizante, a conduta é a cessação da exposição, não sua redução parcial.' }
  ],
  comentario: 'Sensibilização é o divisor de águas: antes dela, a exposição é assintomática; depois, doses ínfimas desencadeiam a doença. Daí a regra clínica de que, em agentes sensibilizantes, a conduta é remover a exposição, e não apenas diminuí-la.',
  pegadinha: 'A resposta que propõe reduzir a exposição pela metade parece equilibrada e é clinicamente inadequada para sensibilizantes.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Asma Ocupacional — protocolos do Ministério da Saúde'] },

{ id: 'q-4.1-035', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao registrar o diagnóstico de um agravo relacionado ao trabalho, o médico deve utilizar a codificação apropriada. Sobre esse registro, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O registro deve identificar a doença e, quando possível, a causa externa ou o agente relacionado, permitindo que os sistemas de informação reconheçam o caso como relacionado ao trabalho.', ok: true,
      why: 'Correta. Registrar apenas o diagnóstico clínico, sem qualquer marcador de relação com o trabalho, é o que produz a invisibilidade estatística desses agravos.' },
    { t: 'A codificação da doença basta, sendo desnecessário qualquer registro sobre a ocupação ou o agente.', ok: false,
      why: 'Errada. Sem informação ocupacional o sistema não distingue o caso relacionado ao trabalho de qualquer outro.' },
    { t: 'O registro de agravo relacionado ao trabalho é facultativo e depende de autorização do empregador.', ok: false,
      why: 'Errada. A notificação de agravos relacionados ao trabalho é obrigação sanitária e não se subordina a autorização da empresa.' },
    { t: 'O sigilo médico impede que o diagnóstico seja informado em qualquer sistema de notificação.', ok: false,
      why: 'Errada. A notificação compulsória é exceção legítima ao sigilo, feita nos canais oficiais e com finalidade sanitária.' },
    { t: 'A codificação por agente é usada apenas em intoxicações, não se aplicando a agravos físicos ou biológicos.', ok: false,
      why: 'Errada. A lógica de identificar o agente ou a circunstância aplica-se a agravos de diferentes naturezas.' }
  ],
  comentario: 'Sem marcador de relação com o trabalho no registro, o agravo desaparece das estatísticas. Notificação compulsória é exceção legítima ao sigilo e independe de anuência do empregador.',
  pegadinha: 'Invocar o sigilo para não notificar é erro ético e sanitário recorrente. A notificação é dever legal e se dá em canal oficial.',
  refs: ['Notificação compulsória em saúde do trabalhador', 'Código de Ética Médica — sigilo e dever legal'] },

{ id: 'q-4.1-036', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre agravos com o trabalho como causa necessária, assinale a alternativa que reúne apenas exemplos corretos:',
  alts: [
    { t: 'Silicose, asbestose, mesotelioma relacionado ao asbesto, intoxicação por chumbo e perda auditiva induzida por ruído ocupacional.', ok: true,
      why: 'Correta. Todos dependem de exposição a agente específico presente no trabalho, sem a qual a doença não se produz.' },
    { t: 'Silicose, hipertensão arterial, dermatite de contato irritativa e lombalgia inespecífica.', ok: false,
      why: 'Errada. Hipertensão e lombalgia inespecífica são doenças comuns e a dermatite irritativa pode ter causas não ocupacionais.' },
    { t: 'Asbestose, câncer de pulmão, transtorno de ansiedade e varizes.', ok: false,
      why: 'Errada. Apenas a asbestose se enquadra; os demais têm múltiplas causas ou são doenças comuns.' },
    { t: 'Mesotelioma, tuberculose pulmonar, diabetes e presbiacusia.', ok: false,
      why: 'Errada. Tuberculose, diabetes e presbiacusia ocorrem independentemente de exposição ocupacional.' },
    { t: 'Beriliose, bissinose, burnout e cloracne.', ok: false,
      why: 'Errada. Beriliose, bissinose e cloracne dependem de agentes específicos, mas o burnout resulta de fatores organizacionais e não configura o mesmo tipo de causalidade por agente específico.' }
  ],
  comentario: 'Regra prática: se a doença não existe sem aquele agente, é causa necessária. Silicose, asbestose, mesotelioma, saturnismo, benzenismo, beriliose, bissinose, cloracne e perda auditiva induzida por ruído são os exemplos que a prova repete.',
  pegadinha: 'Listas mistas são a técnica preferida da banca: basta um item impróprio para invalidar todo o conjunto. Leia até o fim antes de decidir.',
  refs: ['Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde', 'Schilling, R.S.F.'] },

{ id: 'q-4.1-037', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de call center apresenta disfonia crônica. Ao aplicar a lógica de patologia do trabalho, o médico observa que a queixa é frequente entre as colegas do mesmo setor e que o ambiente tem acústica inadequada e metas de tempo de atendimento. Qual conduta traduz melhor o raciocínio de patologia do trabalho?',
  alts: [
    { t: 'Caracterizar o agravo como relacionado ao trabalho, encaminhar para avaliação e reabilitação vocal e, simultaneamente, propor intervenção sobre condições ambientais e organizacionais do setor, dado o padrão coletivo da queixa.', ok: true,
      why: 'Correta. A conduta correta combina cuidado individual e intervenção sobre determinantes coletivos, ambientais e organizacionais.' },
    { t: 'Tratar apenas o quadro individual, uma vez que disfonia é queixa comum na população geral.', ok: false,
      why: 'Errada. A frequência populacional não anula o padrão coletivo observado no setor, que é sinal de determinante comum.' },
    { t: 'Afastar definitivamente a trabalhadora da função, por ser a única medida efetiva.', ok: false,
      why: 'Errada. Afastamento definitivo sem tentativa de adequação ambiental e organizacional é medida desproporcional e não protege as demais.' },
    { t: 'Solicitar apenas exame laringoscópico e aguardar o resultado antes de qualquer outra ação.', ok: false,
      why: 'Errada. A avaliação laringológica é necessária, mas não justifica suspender a investigação das condições de trabalho.' },
    { t: 'Registrar como doença comum, pois não há agente físico ou químico envolvido.', ok: false,
      why: 'Errada. Fatores organizacionais e ambientais são reconhecidos como determinantes de agravos relacionados ao trabalho, mesmo sem agente químico ou físico clássico.' }
  ],
  comentario: 'Patologia do trabalho não se limita a agentes químicos e físicos: organização do trabalho, demanda vocal, acústica e metas são determinantes reconhecidos. Um padrão coletivo de queixa em um setor é indício de causa comum e pede intervenção no ambiente.',
  pegadinha: 'A alternativa que exige agente físico ou químico para admitir relação com o trabalho reproduz uma concepção ultrapassada de causalidade ocupacional.',
  refs: ['Distúrbio de Voz Relacionado ao Trabalho — Ministério da Saúde', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-4.1-038', tema: '4.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a diferença entre exposição, dose interna e efeito biológico em patologia do trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A concentração ambiental do agente é a medida mais fiel da dose absorvida pelo trabalhador, porque considera todas as vias de absorção.', ok: true,
      why: 'É a afirmação FALSA e por isso a resposta. A medida ambiental capta a via inalatória e não contempla absorção cutânea nem digestiva, além de ignorar carga de trabalho, uso e eficácia de proteção e variabilidade individual.' },
    { t: 'A dose interna depende também da absorção cutânea, do esforço físico e da eficácia real da proteção utilizada.', ok: false,
      why: 'Verdadeira. Esses fatores explicam por que trabalhadores no mesmo ambiente podem ter doses internas muito diferentes.' },
    { t: 'O efeito biológico precoce pode ser detectado antes da manifestação clínica da doença.', ok: false,
      why: 'Verdadeira. É essa a finalidade dos indicadores de efeito na vigilância.' },
    { t: 'Alguns agentes são absorvidos de forma relevante pela pele, o que exige atenção especial ao tipo de luva utilizada.', ok: false,
      why: 'Verdadeira. A absorção cutânea é relevante para diversos solventes e agrotóxicos, e a escolha do material da luva é determinante.' },
    { t: 'A ausência de sintomas não garante ausência de dose interna significativa.', ok: false,
      why: 'Verdadeira. Fases subclínicas com dose interna elevada são a regra em intoxicações crônicas.' }
  ],
  comentario: 'Exposição ambiental não é sinônimo de dose interna. Absorção cutânea, esforço físico, ventilação pulmonar, eficácia real da proteção e variabilidade metabólica separam os dois conceitos. Por isso monitoramento ambiental e biológico se complementam.',
  pegadinha: 'A afirmação falsa acrescenta "porque considera todas as vias de absorção", que é exatamente a limitação da medida ambiental. Ler a justificativa da frase é o que revela o erro.',
  refs: ['Mendes, R. — Patologia do Trabalho', 'Toxicologia Ocupacional'] },

/* ==================== 4.2 — Doenças Relacionadas ao Trabalho ==================== */

{ id: 'q-4.2-010', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Operadora de caixa de supermercado, 39 anos, sete anos na função, refere parestesia noturna em polegar, indicador e médio da mão direita, que a desperta e melhora ao sacudir a mão. Ao exame, Phalen e Tinel positivos, sem atrofia tenar. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é compatível com síndrome do túnel do carpo, e a eletroneuromiografia normal em fase inicial não exclui o diagnóstico, que é fundamentalmente clínico.', ok: true,
      why: 'Correta. A distribuição sensitiva do mediano com predomínio noturno e manobras provocativas positivas define o quadro; o exame eletrofisiológico pode ser normal em fases iniciais.' },
    { t: 'A distribuição descrita corresponde ao território do nervo ulnar, sugerindo compressão no cotovelo.', ok: false,
      why: 'Errada. O ulnar inerva o quinto dedo e a metade ulnar do quarto; a distribuição descrita é do mediano.' },
    { t: 'A ausência de atrofia tenar afasta o diagnóstico.', ok: false,
      why: 'Errada. A atrofia é achado tardio; sua ausência é a regra nas fases iniciais e intermediárias.' },
    { t: 'O tratamento inicial indicado é a liberação cirúrgica imediata, independentemente da gravidade.', ok: false,
      why: 'Errada. Em quadros leves a moderados sem déficit motor, iniciam-se medidas conservadoras e adequação do posto antes da indicação cirúrgica.' },
    { t: 'Como se trata de doença de alta prevalência, não cabe investigar relação com o trabalho.', ok: false,
      why: 'Errada. A prevalência geral não afasta a contribuição de repetitividade, força e postura do posto de trabalho.' }
  ],
  comentario: 'Túnel do carpo: parestesia noturna no território do mediano, alívio ao sacudir a mão, Phalen e Tinel positivos, atrofia tenar tardia. Diagnóstico clínico; eletroneuromiografia confirma e gradua, mas normal não exclui. Conduta inicial conservadora com intervenção ergonômica.',
  pegadinha: 'Usar exame eletrofisiológico normal para negar o diagnóstico e o nexo é o erro clássico em perícia de LER/DORT.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-011', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de linha de montagem, 45 anos, dor na face lateral do cotovelo direito que piora ao segurar objetos e à extensão resistida do punho, sem parestesias. Qual é o diagnóstico mais provável e a conduta apropriada?',
  alts: [
    { t: 'Epicondilite lateral, cuja conduta combina controle da dor, ajuste da tarefa quanto a força e preensão e retorno progressivo, e não repouso prolongado isolado.', ok: true,
      why: 'Correta. Dor lateral com piora à extensão resistida do punho caracteriza a epicondilite lateral, e o tratamento efetivo depende de modificar a exigência de preensão e força na tarefa.' },
    { t: 'Epicondilite medial, típica de atividades de extensão do punho.', ok: false,
      why: 'Errada. A epicondilite medial afeta a face interna e relaciona-se a flexão e pronação, não à extensão.' },
    { t: 'Síndrome do túnel cubital, indicada pela dor lateral sem parestesia.', ok: false,
      why: 'Errada. O quadro do túnel cubital cursa com parestesia no quarto e quinto dedos, ausente no caso.' },
    { t: 'Tenossinovite de De Quervain, confirmada pela dor à extensão do punho.', ok: false,
      why: 'Errada. A De Quervain acomete a face radial do punho, com dor à manobra que estira os tendões do polegar, e não o epicôndilo.' },
    { t: 'Bursite olecraniana, sugerida pela dor à preensão de objetos.', ok: false,
      why: 'Errada. A bursite olecraniana cursa com abaulamento e dor na ponta do cotovelo, sem relação com extensão resistida do punho.' }
  ],
  comentario: 'Epicondilite lateral: dor no epicôndilo lateral, piora à extensão resistida do punho e à preensão. Medial: face interna, flexão e pronação. De Quervain: face radial do punho, tendões do polegar. Túnel cubital: parestesia ulnar. O tratamento sem correção da tarefa recidiva.',
  pegadinha: 'Trocar o movimento provocativo entre epicondilite lateral e medial é a inversão explorada. Extensão do punho aponta para o lado externo; flexão e pronação, para o interno.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-012', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Operador de britadeira, 12 anos na função, apresenta episódios de palidez súbita e bem delimitada nos dedos das duas mãos, desencadeados pelo frio, seguidos de cianose e rubor, além de parestesias e redução de força de preensão. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro corresponde à síndrome da vibração mão-braço, com componente vascular, neurossensorial e osteoarticular, e a conduta central é a redução ou cessação da exposição à vibração, pois o quadro pode se tornar irreversível.', ok: true,
      why: 'Correta. O fenômeno vasoespástico digital em usuário de ferramenta vibratória, com componente sensitivo associado, define a síndrome; o afastamento da vibração é a medida determinante do prognóstico.' },
    { t: 'Trata-se de fenômeno de Raynaud primário, cujo tratamento independe da exposição ocupacional.', ok: false,
      why: 'Errada. O Raynaud primário costuma iniciar em mulheres jovens, sem exposição vibratória, e o contexto ocupacional aqui é determinante.' },
    { t: 'O quadro é típico de síndrome do túnel do carpo isolada.', ok: false,
      why: 'Errada. O túnel do carpo não produz palidez digital episódica desencadeada pelo frio.' },
    { t: 'A conduta indicada é manter a exposição e prescrever vasodilatadores, medida suficiente para deter a progressão.', ok: false,
      why: 'Errada. Nenhum tratamento farmacológico substitui a remoção do agente causal na síndrome da vibração.' },
    { t: 'A ausência de alteração em exames laboratoriais de autoimunidade descarta qualquer causa vascular.', ok: false,
      why: 'Errada. Autoanticorpos negativos são esperados na forma ocupacional e servem para afastar doenças do tecido conjuntivo, não para excluir causa vascular.' }
  ],
  comentario: 'Síndrome da vibração mão-braço: ferramentas vibratórias, dedos brancos desencadeados pelo frio, parestesias, perda de destreza e de força. Componentes vascular, neurossensorial e osteoarticular. Reversibilidade depende de afastamento precoce; casos avançados não regridem.',
  pegadinha: 'Rotular como Raynaud primário sem considerar a exposição vibratória é o erro que perde o diagnóstico e o nexo. Perfil demográfico e história ocupacional separam os dois.',
  refs: ['Escala de Stockholm', 'Protocolo de agravos por vibração — Ministério da Saúde'] },

{ id: 'q-4.2-013', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de calçados, exposto a colas contendo solventes aromáticos por oito anos, apresenta hemograma com leucopenia e neutropenia, macrocitose e plaquetopenia leve. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere mielotoxicidade por benzeno, cuja alteração hematológica pode preceder sintomas, exige afastamento imediato da exposição e acompanhamento prolongado pelo risco de evolução para displasia e leucemia.', ok: true,
      why: 'Correta. Citopenias com macrocitose em exposto a solventes aromáticos apontam para benzenismo, agravo que exige afastamento definitivo da exposição e seguimento hematológico continuado.' },
    { t: 'Trata-se de achado inespecífico que só demanda investigação se houver anemia grave.', ok: false,
      why: 'Errada. Leucopenia com neutropenia é justamente uma das alterações mais precoces e não deve aguardar anemia para ser investigada.' },
    { t: 'Havendo normalização do hemograma após afastamento, fica descartado risco futuro.', ok: false,
      why: 'Errada. A normalização não elimina o risco de displasia e de neoplasia hematológica, e o acompanhamento deve continuar.' },
    { t: 'A conduta adequada é manter o trabalhador na função com hemogramas semestrais até que surjam sintomas.', ok: false,
      why: 'Errada. Manter a exposição diante de alteração hematológica é inaceitável, e o benzeno não tem nível seguro estabelecido.' },
    { t: 'A dosagem de indicador biológico urinário normal em coleta isolada exclui exposição relevante ao agente.', ok: false,
      why: 'Errada. Indicadores urinários refletem exposição recente e podem estar normais após dias sem contato, sem excluir exposição acumulada.' }
  ],
  comentario: 'Benzenismo: agente mielotóxico e leucemogênico, sem limiar seguro. Leucopenia com neutropenia, macrocitose e plaquetopenia estão entre as alterações mais precoces. Conduta: afastar definitivamente da exposição, notificar e manter seguimento hematológico prolongado.',
  pegadinha: 'A normalização do hemograma após o afastamento gera falsa sensação de cura. O risco oncológico persiste e o seguimento também.',
  refs: ['Protocolo de Atenção à Saúde dos Trabalhadores Expostos ao Benzeno — Ministério da Saúde'] },

{ id: 'q-4.2-014', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de reciclagem de baterias apresenta cólica abdominal difusa, constipação, palidez e fraqueza em extensores do punho. Hemograma mostra anemia com pontilhado basófilo em hemácias. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O conjunto sugere intoxicação por chumbo, que compromete a síntese do heme, cursa com neuropatia predominantemente motora de extensores e exige afastamento imediato da exposição.', ok: true,
      why: 'Correta. Cólica, anemia com pontilhado basófilo e fraqueza de extensores compõem a tríade clássica do saturnismo, cuja primeira medida é interromper a absorção.' },
    { t: 'A neuropatia do chumbo é caracteristicamente sensitiva e distal, poupando a força muscular.', ok: false,
      why: 'Errada, é uma inversão. A neuropatia do chumbo é tipicamente motora, com predileção pelos extensores, produzindo a mão caída.' },
    { t: 'O quadro corresponde a intoxicação por n-hexano, que produz cólica abdominal e pontilhado basófilo.', ok: false,
      why: 'Errada. O n-hexano causa polineuropatia sensitivo-motora distal, sem cólica abdominal nem alteração da síntese do heme.' },
    { t: 'A anemia do saturnismo é caracteristicamente megaloblástica por deficiência de vitamina B12.', ok: false,
      why: 'Errada. A anemia relaciona-se à inibição de enzimas da via de síntese do heme, não à deficiência de B12.' },
    { t: 'Havendo indicador biológico dentro do valor de referência, o diagnóstico está afastado independentemente da clínica.', ok: false,
      why: 'Errada. Valores de referência não anulam quadro clínico compatível, e o chumbo se deposita em tecido ósseo, com redistribuição ao longo do tempo.' }
  ],
  comentario: 'Saturnismo: cólica abdominal, constipação, anemia com pontilhado basófilo, neuropatia motora de extensores (mão caída), hipertensão e nefropatia. Interferência na síntese do heme explica a anemia. Conduta inicial e mais importante: afastar da exposição.',
  pegadinha: 'A inversão do padrão neuropático — dizer que a neuropatia do chumbo é sensitiva — é a armadilha; guarde "chumbo, motor, extensor, mão caída".',
  refs: ['Protocolo de Intoxicação por Chumbo — Ministério da Saúde'] },

{ id: 'q-4.2-015', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria têxtil que manipula corantes à base de anilinas chega ao pronto atendimento com cianose intensa de lábios e extremidades, sangue de coloração achocolatada e saturação periférica que não melhora com oxigênio suplementar. Qual é a hipótese e a conduta?',
  alts: [
    { t: 'Metemoglobinemia adquirida por agente oxidante ocupacional, com necessidade de remoção da roupa contaminada, descontaminação da pele e consideração de antídoto específico conforme gravidade.', ok: true,
      why: 'Correta. Cianose desproporcional, sangue escuro e ausência de resposta ao oxigênio caracterizam metemoglobinemia; anilinas e nitroderivados são absorvidos também pela pele, o que torna a descontaminação parte do tratamento.' },
    { t: 'Intoxicação por monóxido de carbono, sugerida pela cianose e pela ausência de resposta ao oxigênio.', ok: false,
      why: 'Errada. Na intoxicação por monóxido a coloração típica não é cianótica dessa forma e a resposta ao oxigênio em alta concentração é justamente a base do tratamento.' },
    { t: 'Crise asmática grave, indicada pela dessaturação persistente.', ok: false,
      why: 'Errada. Não há broncoespasmo descrito e a dessaturação da metemoglobinemia não se acompanha do quadro respiratório obstrutivo.' },
    { t: 'Como o agente é absorvido apenas por via inalatória, basta remover o paciente do ambiente.', ok: false,
      why: 'Errada. A absorção cutânea é relevante para anilinas e nitroderivados, e manter roupa contaminada mantém a absorção.' },
    { t: 'A oximetria de pulso é o método definitivo para quantificar a gravidade nesse quadro.', ok: false,
      why: 'Errada. A oximetria convencional é falha nessa condição, e a quantificação exige medida específica da fração de metemoglobina.' }
  ],
  comentario: 'Metemoglobinizantes ocupacionais (anilinas, nitrobenzeno, nitritos): cianose que não responde ao oxigênio, sangue achocolatado, oximetria não confiável. Absorção cutânea importante — remover roupas e descontaminar é parte do tratamento, junto do antídoto quando indicado.',
  pegadinha: 'Confiar na oximetria de pulso e insistir em oxigênio isolado atrasa o diagnóstico. A pista é a discordância entre cianose intensa e ausência de doença cardiopulmonar.',
  refs: ['Toxicologia Ocupacional', 'Protocolos de intoxicações exógenas — Ministério da Saúde'] },

{ id: 'q-4.2-016', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Cortador de cana, 32 anos, trabalha sob calor intenso com ingestão hídrica insuficiente e episódios repetidos de mal-estar ao longo das safras. Apresenta agora elevação de creatinina sem outras causas evidentes. Sobre nefropatias relacionadas ao trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A exposição repetida ao estresse térmico com desidratação e esforço extremo é associada a lesão renal aguda recorrente e a doença renal crônica, e a prevenção depende de hidratação, pausas e sombra, além de vigilância da função renal.', ok: true,
      why: 'Correta. O padrão de lesão renal em trabalhadores de calor extremo com esforço intenso e reposição inadequada é reconhecido, e as medidas organizacionais são o eixo da prevenção.' },
    { t: 'Somente metais pesados causam nefropatia ocupacional, de modo que a hipótese deve ser descartada sem dosagem de metais alterada.', ok: false,
      why: 'Errada. Metais são causas importantes, mas não exclusivas; calor, esforço e solventes também se associam a dano renal.' },
    { t: 'O cádmio caracteristicamente produz glomerulonefrite rapidamente progressiva com hematúria dismórfica.', ok: false,
      why: 'Errada. O cádmio produz classicamente disfunção tubular proximal, com proteinúria de baixo peso molecular, e não esse padrão glomerular.' },
    { t: 'A nefropatia por chumbo se manifesta tipicamente como síndrome nefrótica de instalação abrupta.', ok: false,
      why: 'Errada. O padrão do chumbo é de nefropatia intersticial crônica, podendo associar-se a hiperuricemia e gota.' },
    { t: 'Achado de proteinúria em trabalhador exposto dispensa investigação se a pressão arterial estiver normal.', ok: false,
      why: 'Errada. Proteinúria em exposto é sinal de alerta e demanda investigação independentemente da pressão arterial.' }
  ],
  comentario: 'Nefropatias ocupacionais: cádmio dá disfunção tubular proximal com proteinúria de baixo peso molecular; chumbo dá nefrite intersticial crônica com hiperuricemia; mercúrio associa-se a lesão glomerular; solventes têm associação com glomerulopatias; calor extremo com esforço e desidratação repetidos leva a lesão aguda recorrente e doença crônica.',
  pegadinha: 'A troca de padrões entre cádmio (tubular) e mercúrio (glomerular) é a inversão preferida; e restringir nefropatia ocupacional a metais deixa passar o quadro relacionado ao calor.',
  refs: ['Nefrologia Ocupacional', 'Protocolos de exposição a metais — Ministério da Saúde'] },

{ id: 'q-4.2-017', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de plásticos, exposto a cloreto de vinila por 15 anos, apresenta fenômeno de Raynaud, lesões de reabsorção das falanges distais e alteração hepática em exame de imagem. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O conjunto de Raynaud, acro-osteólise e alteração hepática é característico da exposição ao cloreto de vinila, agente associado ao angiossarcoma hepático, o que exige investigação hepática dirigida e afastamento da exposição.', ok: true,
      why: 'Correta. Essa tríade é a apresentação clássica da doença do cloreto de vinila, e o angiossarcoma hepático é a neoplasia sentinela dessa exposição.' },
    { t: 'O quadro sugere hepatotoxicidade por tetracloreto de carbono, com necrose centrolobular aguda.', ok: false,
      why: 'Errada. O tetracloreto produz hepatotoxicidade aguda com necrose centrolobular, sem acro-osteólise nem associação com angiossarcoma.' },
    { t: 'A associação mais consistente do cloreto de vinila é com carcinoma hepatocelular em cirróticos.', ok: false,
      why: 'Errada. A associação característica e reconhecida é com angiossarcoma hepático.' },
    { t: 'A acro-osteólise descrita indica gota tofácea e afasta causa ocupacional.', ok: false,
      why: 'Errada. A reabsorção de falanges distais nesse contexto é achado ocupacional descrito, com apresentação distinta da artropatia gotosa.' },
    { t: 'Como as alterações são reversíveis com o afastamento, não há indicação de seguimento a longo prazo.', ok: false,
      why: 'Errada. O risco neoplásico de longa latência impõe seguimento prolongado mesmo após cessada a exposição.' }
  ],
  comentario: 'Cloreto de vinila: Raynaud, esclerodermia-like, acro-osteólise, fibrose portal e angiossarcoma hepático. É exemplo de agente cuja neoplasia é tão específica que funciona como marcador de exposição. Latência longa exige seguimento após o afastamento.',
  pegadinha: 'A troca do tumor hepático — carcinoma hepatocelular no lugar de angiossarcoma — é a armadilha construída para quem lembra apenas "fígado".',
  refs: ['IARC Monographs', 'Hepatopatias Ocupacionais'] },

{ id: 'q-4.2-018', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Soldador de estruturas metálicas comparece após episódio de dor ocular intensa bilateral, sensação de areia, lacrimejamento e fotofobia iniciados cerca de oito horas após jornada em que houve falha do uso da máscara. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de ceratoconjuntivite actínica por radiação ultravioleta, quadro doloroso de início tardio após a exposição, geralmente autolimitado, cujo controle depende de proteção ocular adequada durante a soldagem.', ok: true,
      why: 'Correta. O intervalo de várias horas entre a exposição e o início dos sintomas é característico da lesão actínica corneana, que evolui para resolução com medidas sintomáticas.' },
    { t: 'O quadro corresponde a catarata por radiação infravermelha, de instalação aguda.', ok: false,
      why: 'Errada. A catarata associada a radiação infravermelha é de instalação crônica e indolor, sem esse quadro agudo.' },
    { t: 'Trata-se de queimadura química por álcali, cuja conduta é a neutralização com solução ácida.', ok: false,
      why: 'Errada. Não há exposição química descrita, e neutralizar queimadura ocular é conduta contraindicada — a orientação é irrigação abundante.' },
    { t: 'O início tardio dos sintomas afasta relação com a exposição ocorrida na jornada.', ok: false,
      why: 'Errada, é justamente o inverso. O intervalo de horas é o comportamento esperado dessa lesão.' },
    { t: 'A lesão descrita é irreversível e evolui invariavelmente para perda visual permanente.', ok: false,
      why: 'Errada. O epitélio corneano se regenera e o quadro costuma resolver-se em poucos dias.' }
  ],
  comentario: 'Ceratoconjuntivite actínica do soldador: exposição a ultravioleta, sintomas com algumas horas de latência, dor intensa, fotofobia, sensação de corpo estranho, bilateral, autolimitada. Distingue-se da catarata por infravermelho, crônica e indolor, e das queimaduras químicas, de início imediato.',
  pegadinha: 'O intervalo entre a exposição e o início da dor faz o candidato descartar o nexo. Nessa lesão, o atraso é a assinatura diagnóstica.',
  refs: ['Oftalmologia Ocupacional', 'Radiações não ionizantes — saúde ocupacional'] },

{ id: 'q-4.2-019', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Trabalhador de indústria química sofre respingo de solução alcalina no olho. Sobre a conduta imediata, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A irrigação abundante e prolongada com água ou solução fisiológica deve ser iniciada imediatamente no local, antes mesmo do transporte, pois queimaduras por álcali penetram progressivamente e o tempo até a irrigação é determinante do prognóstico.', ok: true,
      why: 'Correta. Álcalis produzem necrose de liquefação e continuam penetrando; o fator prognóstico mais importante é a precocidade e a duração da irrigação.' },
    { t: 'Deve-se neutralizar o álcali com solução ácida diluída antes da irrigação.', ok: false,
      why: 'Errada. A neutralização é contraindicada por gerar calor e agravar a lesão.' },
    { t: 'Queimaduras por ácidos são mais graves que as por álcalis, por penetrarem mais profundamente.', ok: false,
      why: 'Errada, é a inversão. Ácidos tendem a produzir necrose de coagulação que limita a penetração; álcalis penetram mais e são mais graves.' },
    { t: 'A irrigação deve ser breve, para não retardar a avaliação oftalmológica.', ok: false,
      why: 'Errada. A irrigação prolongada é a própria prioridade e não deve ser interrompida para acelerar o encaminhamento.' },
    { t: 'Havendo alívio da dor, pode-se suspender a irrigação e liberar o trabalhador.', ok: false,
      why: 'Errada. O alívio sintomático não indica remoção completa do agente, e a avaliação especializada continua necessária.' }
  ],
  comentario: 'Queimadura ocular química: irrigar imediatamente, com grande volume e por tempo prolongado; nunca neutralizar. Álcalis (necrose de liquefação) são mais graves que ácidos (necrose de coagulação). Tempo até a irrigação é o principal determinante do desfecho.',
  pegadinha: 'A inversão "ácido é pior que álcali" é a mais cobrada nesse tema; e a tentação de neutralizar é o erro de conduta mais perigoso.',
  refs: ['Oftalmologia Ocupacional', 'Primeiros socorros em acidentes químicos'] },

{ id: 'q-4.2-020', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Enfermeira de central de quimioterapia, 29 anos, planeja engravidar e questiona sobre riscos reprodutivos de sua atividade. Sobre distúrbios da reprodução relacionados ao trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Antineoplásicos manipulados sem controle adequado estão associados a desfechos reprodutivos adversos, e a conduta correta combina medidas técnicas de contenção, procedimentos seguros de manipulação e avaliação da possibilidade de remanejamento, e não apenas orientação individual.', ok: true,
      why: 'Correta. O risco é reconhecido e a resposta é primariamente de engenharia e de procedimento, com o remanejamento avaliado como medida complementar quando o controle não é suficiente.' },
    { t: 'Riscos reprodutivos ocupacionais dizem respeito apenas a trabalhadoras, não havendo efeito sobre a fertilidade masculina.', ok: false,
      why: 'Errada. Diversos agentes afetam a fertilidade masculina, com o chumbo e alguns pesticidas entre os exemplos consagrados.' },
    { t: 'A ausência de sintomas na trabalhadora garante ausência de risco para uma gestação futura.', ok: false,
      why: 'Errada. Efeitos reprodutivos podem ocorrer com exposições que não produzem sintomas na trabalhadora.' },
    { t: 'O uso de luvas de procedimento comuns é medida suficiente para manipulação segura de antineoplásicos.', ok: false,
      why: 'Errada. A manipulação exige barreiras específicas e sistemas de contenção, não sendo suficiente a luva comum.' },
    { t: 'A gravidez confirmada é a única situação em que se justifica qualquer medida de proteção nessa atividade.', ok: false,
      why: 'Errada. A proteção deve existir permanentemente para todos os trabalhadores, independentemente de gestação.' }
  ],
  comentario: 'Riscos reprodutivos ocupacionais atingem ambos os sexos e incluem infertilidade, abortamento, malformação, prematuridade e efeitos no desenvolvimento. Agentes clássicos: chumbo, mercúrio orgânico, solventes, antineoplásicos, gases anestésicos residuais, radiação ionizante e agentes infecciosos.',
  pegadinha: 'Reduzir a prevenção ao período da gestação e à trabalhadora individualmente ignora o efeito masculino e o princípio de controle permanente da exposição.',
  refs: ['Saúde reprodutiva e trabalho — Ministério da Saúde', 'NR-32'] },

{ id: 'q-4.2-021', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de fábrica de explosivos, que manipula ésteres de nitrato, apresenta episódios de dor precordial que ocorrem tipicamente nas segundas-feiras, após o fim de semana afastado do trabalho, e cedem ao retornar à exposição. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é compatível com angina de retirada por abstinência de nitratos ocupacionais, fenômeno reconhecido em trabalhadores dessa indústria, cujo manejo envolve redução gradual da exposição e vigilância cardiovascular.', ok: true,
      why: 'Correta. A exposição contínua a nitratos provoca adaptação vasomotora, e a interrupção abrupta nos períodos de folga desencadeia vasoespasmo, com angina e risco de eventos.' },
    { t: 'A relação com a segunda-feira indica origem exclusivamente psicossomática, sem risco cardiovascular.', ok: false,
      why: 'Errada. O padrão temporal aqui tem explicação farmacológica, e o risco de evento coronariano é real.' },
    { t: 'O quadro corresponde a bissinose, doença que também piora às segundas-feiras.', ok: false,
      why: 'Errada. A bissinose é respiratória, ligada a poeira de algodão, e cursa com opressão torácica e queda de função pulmonar, não com angina que cede ao retorno à exposição.' },
    { t: 'Trata-se de febre dos fumos metálicos, quadro de repetição semanal em soldadores.', ok: false,
      why: 'Errada. A febre dos fumos metálicos é síndrome febril autolimitada, sem relação com ésteres de nitrato nem com dor anginosa.' },
    { t: 'A conduta indicada é o afastamento abrupto e definitivo da exposição, sem qualquer transição.', ok: false,
      why: 'Errada. O afastamento abrupto é justamente o gatilho do fenômeno; a retirada deve ser conduzida com cautela e acompanhamento.' }
  ],
  comentario: 'Angina de retirada em expostos a nitratos: sintomas nos períodos de afastamento, alívio ao retornar à exposição. É contraintuitivo — a doença aparece longe do trabalho. Diferencia-se de bissinose e febre dos fumos metálicos, que pioram ao retomar a exposição na segunda-feira.',
  pegadinha: 'Quadros com padrão de segunda-feira são vários e opostos entre si: uns pioram ao voltar (bissinose, fumos metálicos), outros pioram ao sair (nitratos). O sentido da relação temporal é a chave.',
  refs: ['Cardiologia Ocupacional', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-022', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a relação entre trabalho e doenças cardiovasculares, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'Por serem doenças de causa multifatorial e alta prevalência, agravos cardiovasculares nunca podem ser reconhecidos como relacionados ao trabalho.', ok: true,
      why: 'É a afirmação FALSA e por isso a resposta. Multicausalidade é exatamente a situação em que o trabalho é reconhecido como fator contributivo, e há agravos cardiovasculares na lista de doenças relacionadas ao trabalho.' },
    { t: 'A exposição prolongada a dissulfeto de carbono associa-se a aterosclerose acelerada e doença isquêmica.', ok: false,
      why: 'Verdadeira. É uma das associações químicas mais bem estabelecidas em cardiologia ocupacional.' },
    { t: 'A exposição ao monóxido de carbono pode precipitar isquemia miocárdica em portadores de coronariopatia.', ok: false,
      why: 'Verdadeira. A redução da capacidade de transporte de oxigênio reduz o limiar isquêmico.' },
    { t: 'Solventes halogenados podem sensibilizar o miocárdio às catecolaminas, com risco de arritmias graves.', ok: false,
      why: 'Verdadeira. Esse mecanismo explica casos de morte súbita associados à inalação desses solventes.' },
    { t: 'Jornadas prolongadas e trabalho em turnos estão associados a maior risco de eventos cardiovasculares.', ok: false,
      why: 'Verdadeira. A associação é sustentada por evidência epidemiológica consistente.' }
  ],
  comentario: 'Cardiologia ocupacional reúne agentes químicos (dissulfeto de carbono, monóxido de carbono, nitratos, solventes halogenados, chumbo, arsênico), físicos (ruído, calor) e organizacionais (turnos, jornadas longas, alta demanda com baixo controle). Multicausalidade não impede reconhecimento.',
  pegadinha: 'A afirmação falsa usa um argumento verdadeiro — a multicausalidade — para uma conclusão errada. Esse é o formato mais difícil de detectar.',
  refs: ['Lista de Doenças Relacionadas ao Trabalho — Ministério da Saúde', 'Cardiologia Ocupacional'] },

{ id: 'q-4.2-023', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Costureira de confecção, 43 anos, com dor cervical irradiada para o membro superior direito, parestesia em quarto e quinto dedos e piora com elevação prolongada dos braços; pulso radial reduz-se em manobras de abdução e rotação externa do ombro. Qual a hipótese mais provável?',
  alts: [
    { t: 'Síndrome do desfiladeiro torácico, com compressão neurovascular na saída do tórax, que se distingue das compressões distais pelo território sintomático e pela relação com a postura de elevação dos membros.', ok: true,
      why: 'Correta. Sintomas em território ulnar com componente vascular postural e piora com elevação dos braços caracterizam a compressão na região do desfiladeiro.' },
    { t: 'Síndrome do túnel do carpo, indicada pela parestesia em quarto e quinto dedos.', ok: false,
      why: 'Errada. O túnel do carpo compromete o território do mediano, poupando o quinto dedo.' },
    { t: 'Epicondilite medial, sugerida pela irradiação para o membro superior.', ok: false,
      why: 'Errada. Epicondilite medial produz dor localizada na face interna do cotovelo, sem parestesia distal nem alteração de pulso.' },
    { t: 'Tendinite do supraespinal, indicada pela piora com elevação dos braços.', ok: false,
      why: 'Errada. A tendinite do manguito produz dor no arco de movimento sem parestesias em território ulnar nem alteração vascular.' },
    { t: 'Neuropatia diabética, sugerida pela distribuição em dois dedos.', ok: false,
      why: 'Errada. A neuropatia diabética é tipicamente distal e simétrica em bota e luva, sem relação postural nem componente vascular.' }
  ],
  comentario: 'Desfiladeiro torácico: sintomas em território ulnar, piora com elevação e abdução dos membros, possível componente vascular. Diferencie do túnel do carpo (mediano, noturno), do túnel cubital (ulnar com dor no cotovelo) e da radiculopatia cervical (dor irradiada em dermátomo com sinais radiculares).',
  pegadinha: 'Toda parestesia de mão em trabalhadora com trabalho repetitivo tende a ser rotulada como túnel do carpo. O território dos dedos acometidos é o que separa os diagnósticos.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-024', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a conduta diante de um caso confirmado de LER/DORT em trabalhador de linha de produção, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A abordagem deve ser simultaneamente clínica e ergonômica, com análise do posto de trabalho, adequação da tarefa, retorno gradual e acompanhamento, pois tratar o indivíduo e devolvê-lo ao mesmo posto inalterado tende a produzir recidiva.', ok: true,
      why: 'Correta. Sem intervenção sobre a organização e o posto de trabalho, o tratamento individual apenas adia a recorrência.' },
    { t: 'O afastamento prolongado com repouso absoluto é a conduta de escolha em todos os casos.', ok: false,
      why: 'Errada. Repouso prolongado piora o descondicionamento e o prognóstico funcional; a orientação é manutenção de atividade tolerável e retorno progressivo.' },
    { t: 'A emissão de comunicação de acidente do trabalho deve aguardar decisão pericial sobre o nexo.', ok: false,
      why: 'Errada. A comunicação decorre da suspeita fundamentada e não depende de decisão pericial prévia.' },
    { t: 'Havendo fatores psicossociais envolvidos, o caso deixa de ser considerado relacionado ao trabalho.', ok: false,
      why: 'Errada. Fatores psicossociais e organizacionais integram os determinantes reconhecidos dos quadros osteomusculares relacionados ao trabalho.' },
    { t: 'A infiltração local resolve o problema e dispensa modificação da tarefa.', ok: false,
      why: 'Errada. Medidas locais podem aliviar sintomas, mas não alteram a exposição que produziu o quadro.' }
  ],
  comentario: 'Conduta em LER/DORT: diagnóstico clínico e funcional, tratamento com manutenção de atividade tolerável, análise ergonômica com modificação real da tarefa, retorno gradual e acompanhamento, comunicação e notificação. Fatores organizacionais e psicossociais fazem parte do quadro.',
  pegadinha: 'Aguardar a perícia para emitir a comunicação de acidente inverte a ordem: a comunicação é do serviço assistencial diante da suspeita, e a perícia vem depois.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde', 'Lei 8.213/91'] },

{ id: 'q-4.2-025', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de gráfica, exposto por anos a solventes contendo n-hexano, apresenta parestesias distais simétricas em membros inferiores, com progressão ascendente e fraqueza distal. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere polineuropatia tóxica por n-hexano, de padrão sensitivo-motor distal e simétrico, que pode progredir por semanas mesmo após o afastamento antes de iniciar recuperação parcial.', ok: true,
      why: 'Correta. A neuropatia por n-hexano tem esse padrão e é conhecida pelo fenômeno de piora transitória após a interrupção da exposição, seguida de recuperação lenta e por vezes incompleta.' },
    { t: 'A neuropatia por n-hexano é predominantemente motora proximal e assimétrica.', ok: false,
      why: 'Errada. O padrão é distal, simétrico e com componente sensitivo importante.' },
    { t: 'A progressão dos sintomas após o afastamento indica que a causa não é ocupacional.', ok: false,
      why: 'Errada, é uma inversão. A piora nas semanas seguintes ao afastamento é comportamento descrito nessa neuropatia.' },
    { t: 'O quadro é típico de intoxicação por chumbo, com neuropatia motora dos extensores.', ok: false,
      why: 'Errada. A neuropatia do chumbo é motora com predileção por extensores de punho, sem esse padrão sensitivo ascendente.' },
    { t: 'A conduta é manter a exposição em níveis reduzidos, pois a recuperação ocorre independentemente do afastamento.', ok: false,
      why: 'Errada. A interrupção da exposição é condição para qualquer recuperação e não pode ser substituída por redução parcial.' }
  ],
  comentario: 'n-Hexano e metil-n-butilcetona produzem polineuropatia sensitivo-motora distal simétrica, com piora possível após a retirada (coasting) e recuperação lenta. Contrasta com a neuropatia do chumbo, motora e de extensores, e com a do arsênico, dolorosa e distal.',
  pegadinha: 'A piora após o afastamento é usada para negar o nexo. Nessa neuropatia específica, é achado esperado e não argumento contra a origem ocupacional.',
  refs: ['Neurologia Ocupacional', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-026', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de manutenção industrial é encontrado inconsciente em espaço confinado onde havia funcionamento de motor a combustão. Apresenta cefaleia, náusea e confusão nos colegas que tentaram o resgate. Sobre a intoxicação por monóxido de carbono, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A oximetria de pulso convencional pode indicar saturação falsamente normal, e a conduta imediata é a remoção do ambiente com administração de oxigênio em alta concentração, considerando-se oxigenoterapia hiperbárica em casos graves.', ok: true,
      why: 'Correta. A oximetria comum não distingue carboxiemoglobina de oxiemoglobina, e o tratamento se baseia em oxigênio em alta concentração, com indicação de câmara hiperbárica em situações selecionadas.' },
    { t: 'A cianose intensa é o achado clínico mais característico da intoxicação por monóxido.', ok: false,
      why: 'Errada. A coloração descrita classicamente não é cianótica, e a ausência de cianose com hipóxia tecidual é parte da armadilha diagnóstica.' },
    { t: 'A saturação normal na oximetria de pulso permite descartar a intoxicação.', ok: false,
      why: 'Errada. É justamente o falso-normal que retarda o diagnóstico.' },
    { t: 'O quadro se resolve espontaneamente sem risco de sequelas neurológicas.', ok: false,
      why: 'Errada. Há risco de sequelas neuropsiquiátricas, inclusive de aparecimento tardio após aparente recuperação.' },
    { t: 'Os colegas sintomáticos durante o resgate indicam contágio interpessoal do agente.', ok: false,
      why: 'Errada. O acometimento simultâneo decorre da mesma exposição ambiental, característica de espaços confinados, e não de transmissão.' }
  ],
  comentario: 'Monóxido de carbono: gás inodoro, alta afinidade pela hemoglobina, oximetria de pulso não confiável, sintomas inespecíficos que simulam quadro viral. Múltiplas vítimas no mesmo ambiente é o dado que levanta a suspeita. Tratamento com oxigênio em alta concentração, hiperbárico em casos graves. Sequelas tardias são possíveis.',
  pegadinha: 'Confiar na oximetria de pulso normal é o erro central. E o adoecimento dos resgatistas é sinal de ambiente ainda perigoso, não de contágio.',
  refs: ['Toxicologia Ocupacional', 'Trabalho em espaços confinados'] },

{ id: 'q-4.2-027', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Digitadora de dados, 34 anos, com dor difusa em antebraços, sensação de peso e fadiga, sem sinais inflamatórios localizados e com exames de imagem normais. Trabalha com metas de produção elevadas e pausas insuficientes. Sobre a conduta, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A ausência de achado objetivo em exames de imagem não invalida o diagnóstico de quadro doloroso relacionado ao trabalho, e a conduta deve incluir intervenção sobre ritmo, metas e pausas, além do tratamento sintomático.', ok: true,
      why: 'Correta. Muitos quadros relacionados ao trabalho, sobretudo nas fases iniciais, cursam sem alteração de imagem; o determinante organizacional é parte do diagnóstico e do tratamento.' },
    { t: 'Exames de imagem normais indicam simulação e devem motivar retorno imediato à função sem restrições.', ok: false,
      why: 'Errada. Exames normais são frequentes nesses quadros e não autorizam presunção de simulação.' },
    { t: 'A conduta indicada é limitar-se ao uso de anti-inflamatórios até a remissão espontânea.', ok: false,
      why: 'Errada. O tratamento medicamentoso isolado não modifica a exposição que produz e mantém o quadro.' },
    { t: 'Metas e ritmo de trabalho são fatores organizacionais sem relação com adoecimento osteomuscular.', ok: false,
      why: 'Errada. Ritmo, metas, ausência de pausas e controle sobre o trabalho são fatores reconhecidos nesses agravos.' },
    { t: 'Só se justifica investigar o posto de trabalho quando houver mais de cinco casos no mesmo setor.', ok: false,
      why: 'Errada. Não há limiar numérico; o caso individual já indica avaliação da tarefa.' }
  ],
  comentario: 'Quadros osteomusculares relacionados ao trabalho frequentemente não têm tradução em imagem. O diagnóstico é clínico e funcional, e os fatores organizacionais — ritmo, metas, pausas, controle sobre o trabalho — integram tanto a causa quanto a conduta.',
  pegadinha: 'A equação "exame normal igual a simulação" é o preconceito mais prejudicial nesse tema e aparece com frequência como distrator plausível.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde', 'Ergonomia e organização do trabalho'] },

{ id: 'q-4.2-028', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de acumuladores, exposto a arsina em processo de limpeza com ácido, apresenta subitamente hemoglobinúria, icterícia, dor abdominal e queda acentuada de hemoglobina. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é compatível com hemólise intravascular aguda por arsina, com risco de insuficiência renal aguda, exigindo remoção imediata da exposição e suporte intensivo.', ok: true,
      why: 'Correta. A arsina é um dos hemolisantes ocupacionais mais potentes, e a hemoglobinúria maciça leva à lesão renal aguda, que domina o prognóstico.' },
    { t: 'Trata-se de anemia por deficiência de ferro secundária à exposição crônica.', ok: false,
      why: 'Errada. A instalação súbita com hemoglobinúria e icterícia caracteriza hemólise, não carência de ferro.' },
    { t: 'A urina escura descrita indica desidratação e não requer investigação adicional.', ok: false,
      why: 'Errada. Urina escura nesse contexto sugere hemoglobinúria e é sinal de gravidade.' },
    { t: 'O quadro corresponde a metemoglobinemia, com sangue de coloração achocolatada.', ok: false,
      why: 'Errada. Metemoglobinemia cursa com cianose e sangue escuro, sem hemólise maciça nem hemoglobinúria como marca.' },
    { t: 'Como o agente é gasoso, não há risco renal associado.', ok: false,
      why: 'Errada. Justamente o produto da hemólise sobrecarrega e lesa o rim, tornando a insuficiência renal a complicação temida.' }
  ],
  comentario: 'Hemolisantes ocupacionais: arsina e estibina, geradas de forma inadvertida quando ácidos reagem com metais contaminados. Quadro agudo com hemólise intravascular, hemoglobinúria, icterícia e insuficiência renal aguda. Distinguir de metemoglobinemia, que dá cianose sem hemólise.',
  pegadinha: 'Confundir os dois grandes quadros hematológicos agudos ocupacionais — hemólise por arsina e metemoglobinemia por anilinas — é o erro que a questão persegue.',
  refs: ['Toxicologia Ocupacional', 'Hematologia Ocupacional'] },

{ id: 'q-4.2-029', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a síndrome visual relacionada ao trabalho com telas, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Os sintomas de fadiga visual, ardor, visão borrada e cefaleia decorrem de fatores como redução da frequência de piscar, erros refracionais não corrigidos, iluminação e posicionamento inadequados, e não produzem dano estrutural permanente ao olho.', ok: true,
      why: 'Correta. É quadro funcional e reversível, cuja abordagem é ergonômica, refracional e de lubrificação ocular.' },
    { t: 'O uso prolongado de telas causa progressão irreversível de catarata.', ok: false,
      why: 'Errada. Não há relação estabelecida entre uso de monitores e catarata.' },
    { t: 'A conduta principal é a prescrição de colírio anestésico para alívio dos sintomas.', ok: false,
      why: 'Errada. Anestésicos tópicos são contraindicados para uso continuado por risco de lesão corneana.' },
    { t: 'A correção de vício de refração é irrelevante para o quadro.', ok: false,
      why: 'Errada. Erro refracional não corrigido é um dos principais determinantes da astenopia em trabalho com telas.' },
    { t: 'As pausas visuais devem ser evitadas por reduzirem a produtividade e não trazerem benefício comprovado.', ok: false,
      why: 'Errada. Pausas e mudança de foco visual estão entre as medidas recomendadas para reduzir os sintomas.' }
  ],
  comentario: 'Astenopia relacionada a telas: sintomas funcionais reversíveis. Determinantes: piscar reduzido com ressecamento, erro refracional não corrigido, iluminação e reflexos, distância e altura do monitor, ausência de pausas. Sem dano estrutural permanente.',
  pegadinha: 'A crença de que o monitor "danifica a vista" leva a marcar a alternativa da catarata. Sintoma intenso não é sinônimo de lesão anatômica.',
  refs: ['Oftalmologia Ocupacional', 'Ergonomia do trabalho com telas'] },

{ id: 'q-4.2-030', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador da construção civil, 51 anos, apresenta lombalgia aguda após levantamento de carga, sem irradiação, sem déficit neurológico, sem febre, sem perda de peso e sem antecedente neoplásico. Sobre a conduta, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de lombalgia inespecífica, na qual a imagem de rotina não está indicada na ausência de sinais de alerta, e a orientação é manutenção de atividade tolerável com retorno funcional progressivo, associada à revisão das exigências de manuseio de carga.', ok: true,
      why: 'Correta. Sem sinais de alerta, a investigação por imagem não altera a conduta e pode gerar achados incidentais; a intervenção sobre a tarefa é a medida preventiva efetiva.' },
    { t: 'Está indicada ressonância magnética imediata para todos os casos de lombalgia ocupacional aguda.', ok: false,
      why: 'Errada. A imagem precoce sem sinais de alerta não melhora o desfecho e associa-se a mais intervenções desnecessárias.' },
    { t: 'O repouso absoluto no leito por período prolongado acelera a recuperação.', ok: false,
      why: 'Errada. O repouso prolongado atrasa a recuperação funcional e aumenta o risco de cronificação.' },
    { t: 'A presença de alterações degenerativas em radiografia confirmaria o nexo com o trabalho.', ok: false,
      why: 'Errada. Alterações degenerativas são achados frequentes na faixa etária e não estabelecem nexo por si.' },
    { t: 'Sinais de alerta como febre, perda de peso e déficit neurológico progressivo são irrelevantes na abordagem inicial.', ok: false,
      why: 'Errada. É exatamente a pesquisa desses sinais que define quem precisa de investigação imediata.' }
  ],
  comentario: 'Lombalgia ocupacional: a esmagadora maioria é inespecífica. Sem sinais de alerta, não se pede imagem de rotina; mantém-se atividade tolerável, evita-se repouso prolongado e revisa-se a exigência de manuseio de carga. Achados degenerativos não fecham nexo nem diagnóstico.',
  pegadinha: 'Pedir imagem em toda lombalgia gera achados incidentais que rotulam o trabalhador e desviam a conduta do que importa: a tarefa que produziu a sobrecarga.',
  refs: ['Protocolo de Dorsalgias Relacionadas ao Trabalho — Ministério da Saúde'] },

{ id: 'q-4.2-031', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de lavanderia hospitalar, 46 anos, apresenta dor e limitação em ombro direito, com dor à elevação entre 60 e 120 graus, teste de Jobe positivo e dor noturna ao deitar sobre o lado acometido. Qual é a hipótese mais provável e a conduta inicial?',
  alts: [
    { t: 'Síndrome do manguito rotador com acometimento do supraespinal, com conduta inicial conservadora e revisão das tarefas que exigem trabalho com os braços acima da altura dos ombros.', ok: true,
      why: 'Correta. Arco doloroso, teste específico para o supraespinal positivo e dor noturna compõem o quadro; a tarefa com elevação dos braços é o fator ocupacional a corrigir.' },
    { t: 'Capsulite adesiva, caracterizada por arco doloroso com amplitude passiva preservada.', ok: false,
      why: 'Errada. A capsulite cursa com restrição da mobilidade passiva, o que não corresponde ao descrito.' },
    { t: 'Radiculopatia cervical, sugerida pela dor noturna no ombro.', ok: false,
      why: 'Errada. A radiculopatia produz dor irradiada em dermátomo com sinais neurológicos, ausentes no caso.' },
    { t: 'Bursite trocantérica, comum em trabalhadoras com esforço de membros superiores.', ok: false,
      why: 'Errada. A bursite trocantérica é quadro do quadril, sem relação com o ombro.' },
    { t: 'Epicondilite lateral irradiada para o ombro, confirmada pelo teste descrito.', ok: false,
      why: 'Errada. Epicondilite é quadro do cotovelo, e o teste descrito avalia especificamente o supraespinal.' }
  ],
  comentario: 'Manguito rotador: arco doloroso, testes específicos positivos, dor noturna ao deitar sobre o ombro, mobilidade passiva preservada. Trabalho com braços acima da altura dos ombros é o fator ocupacional clássico. Capsulite adesiva se distingue pela restrição passiva.',
  pegadinha: 'A diferença entre manguito e capsulite está na mobilidade passiva: preservada no primeiro, restrita na segunda. Distratores costumam trocar esse detalhe.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-032', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre exposições ocupacionais associadas a hepatopatias, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A elevação de transaminases em trabalhador exposto a solventes deve ser sempre atribuída a etiologia viral ou a consumo de álcool, sem necessidade de avaliar a exposição.', ok: true,
      why: 'É a afirmação FALSA e portanto a resposta. Causas comuns devem ser investigadas, mas a exposição ocupacional a hepatotóxicos precisa entrar no diagnóstico diferencial e ser caracterizada.' },
    { t: 'O tetracloreto de carbono é hepatotóxico com padrão de necrose centrolobular.', ok: false,
      why: 'Verdadeira. É o hepatotóxico ocupacional histórico, com esse padrão característico.' },
    { t: 'A dimetilformamida está associada a hepatite tóxica em trabalhadores expostos.', ok: false,
      why: 'Verdadeira. É associação bem documentada em indústrias que utilizam o solvente.' },
    { t: 'O cloreto de vinila associa-se a fibrose portal e a angiossarcoma hepático.', ok: false,
      why: 'Verdadeira. É a exposição classicamente ligada a esse tumor raro.' },
    { t: 'A associação de exposição a solvente com consumo de álcool pode potencializar a hepatotoxicidade.', ok: false,
      why: 'Verdadeira. A interação entre álcool e solventes hepatotóxicos é reconhecida.' }
  ],
  comentario: 'Hepatotóxicos ocupacionais: tetracloreto de carbono e clorofórmio (necrose centrolobular), dimetilformamida (hepatite tóxica), cloreto de vinila (fibrose portal e angiossarcoma), tricloroetileno (reação de hipersensibilidade sistêmica com hepatite). Álcool potencializa vários deles.',
  pegadinha: 'O uso do álcool como explicação exclusiva para a alteração hepática é a forma mais comum de perder o diagnóstico ocupacional — e a interação entre os dois torna o raciocínio ainda mais necessário.',
  refs: ['Hepatopatias Ocupacionais', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-033', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Pintor industrial que utiliza pistola de alta pressão sofre injeção acidental de tinta na polpa do dedo indicador. Apresenta pequeno orifício de entrada, dor moderada e discreto edema, com aspecto externo pouco expressivo. Qual é a conduta correta?',
  alts: [
    { t: 'Trata-se de emergência cirúrgica, pois a aparência externa subestima a extensão do dano tecidual profundo, com risco de necrose e amputação se houver retardo na exploração e desbridamento.', ok: true,
      why: 'Correta. Lesões por injeção de alta pressão têm apresentação externa enganosa e prognóstico dependente da rapidez da abordagem cirúrgica.' },
    { t: 'Como a lesão externa é mínima, indica-se curativo simples e retorno ao trabalho.', ok: false,
      why: 'Errada. A aparência benigna é justamente a armadilha dessas lesões, cujo dano é profundo e progressivo.' },
    { t: 'A conduta é observação ambulatorial por 72 horas antes de qualquer decisão.', ok: false,
      why: 'Errada. A demora aumenta significativamente o risco de perda do segmento.' },
    { t: 'A infiltração de anestésico local em bloqueio digital é a medida prioritária e suficiente.', ok: false,
      why: 'Errada. Analgesia é medida de suporte e não substitui a exploração cirúrgica urgente.' },
    { t: 'O prognóstico independe do tipo de substância injetada e do tempo até o tratamento.', ok: false,
      why: 'Errada. Tipo de solvente, volume e tempo até a abordagem são determinantes reconhecidos do desfecho.' }
  ],
  comentario: 'Injeção de alta pressão: ferida puntiforme com destruição extensa em planos profundos e disseminação do produto ao longo de bainhas tendíneas. Emergência cirúrgica. Aparência externa não reflete gravidade e o tempo até a abordagem determina o desfecho.',
  pegadinha: 'A dissociação entre a lesão externa mínima e o dano interno grave é o cerne. Tratar como ferimento superficial é o erro que custa o dedo.',
  refs: ['Acidentes do trabalho em atividades industriais', 'Cirurgia da mão — lesões por alta pressão'] },

{ id: 'q-4.2-034', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de siderúrgica exposto a calor intenso é encontrado confuso, com pele quente, temperatura corporal muito elevada e alteração do nível de consciência. Sobre a conduta imediata, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere intermação, emergência médica cuja prioridade é o resfriamento corporal rápido associado ao suporte clínico, pois o tempo de hipertermia se correlaciona com a lesão de órgãos e com a mortalidade.', ok: true,
      why: 'Correta. Hipertermia com disfunção do sistema nervoso central caracteriza a forma grave, e o resfriamento imediato é a intervenção que muda o prognóstico.' },
    { t: 'Trata-se de exaustão pelo calor, quadro sem alteração de consciência, cujo tratamento é apenas repouso e hidratação oral.', ok: false,
      why: 'Errada. A alteração de consciência descrita é o que separa a exaustão da forma grave e obriga conduta de emergência.' },
    { t: 'O resfriamento deve ser adiado até a chegada ao hospital para evitar arritmias.', ok: false,
      why: 'Errada. O resfriamento precoce no local é recomendado e o atraso agrava o dano.' },
    { t: 'A ausência de sudorese é critério obrigatório para o diagnóstico.', ok: false,
      why: 'Errada. A anidrose pode estar ausente, sobretudo na forma associada a esforço; sua ausência não exclui o quadro.' },
    { t: 'Antitérmicos são a base do tratamento nesse quadro.', ok: false,
      why: 'Errada. Antitérmicos não atuam sobre hipertermia por sobrecarga térmica externa; o tratamento é o resfriamento físico.' }
  ],
  comentario: 'Exaustão pelo calor: fraqueza, náusea, sudorese, consciência preservada — repouso, ambiente fresco e reposição. Intermação: hipertermia com disfunção neurológica — emergência, resfriamento imediato, suporte. Antitérmico não tem papel, e a sudorese pode estar presente na forma por esforço.',
  pegadinha: 'Exigir "pele seca" para diagnosticar a forma grave atrasa o tratamento em trabalhadores com esforço físico intenso, que costumam continuar suando.',
  refs: ['Agravos relacionados ao calor ocupacional', 'Protocolos de emergência'] },

{ id: 'q-4.2-035', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de indústria química informa estar grávida e atua em setor com exposição a solventes orgânicos. Sobre a conduta do médico do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A conduta adequada é avaliar a exposição real, remanejar a trabalhadora para atividade sem exposição a agentes de risco reprodutivo e manter as medidas de controle para todo o coletivo, sem transformar a gravidez na única justificativa da proteção.', ok: true,
      why: 'Correta. A gestação exige remanejamento diante de agentes de risco reprodutivo, mas a proteção do conjunto de trabalhadores deve preexistir e permanecer.' },
    { t: 'Basta orientar o uso de máscara e manter a trabalhadora na mesma função durante toda a gestação.', ok: false,
      why: 'Errada. Proteção individual não é medida suficiente diante de agentes com potencial de risco reprodutivo.' },
    { t: 'A trabalhadora deve ser afastada do emprego, com rescisão contratual, por incompatibilidade definitiva com a atividade.', ok: false,
      why: 'Errada. A medida cabível é o remanejamento para atividade compatível, jamais a perda do vínculo.' },
    { t: 'Não há necessidade de qualquer medida antes do segundo trimestre.', ok: false,
      why: 'Errada. O primeiro trimestre é o período de maior vulnerabilidade à organogênese, o que torna a medida mais urgente e não menos.' },
    { t: 'Solventes não atravessam a barreira placentária, de modo que a exposição materna não atinge o concepto.', ok: false,
      why: 'Errada. Diversos solventes orgânicos atravessam a placenta e podem atingir o concepto.' }
  ],
  comentario: 'Trabalhadora gestante exposta a agentes de risco reprodutivo: avaliar exposição real, remanejar para atividade sem exposição, manter salário e vínculo, e conservar as medidas coletivas de controle. O primeiro trimestre é o período mais crítico, o que torna a atuação precoce essencial.',
  pegadinha: 'Adiar a medida para "quando a gravidez avançar" inverte a lógica do risco teratogênico, maior exatamente no início da gestação.',
  refs: ['Saúde reprodutiva e trabalho — Ministério da Saúde', 'Proteção à trabalhadora gestante'] },

{ id: 'q-4.2-036', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a relação entre trabalho em turnos e agravos à saúde, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O trabalho noturno e em turnos associa-se a distúrbios do sono, agravos metabólicos e cardiovasculares e alterações gastrointestinais, e a organização das escalas — sentido do rodízio, velocidade e duração — influencia a magnitude desses efeitos.', ok: true,
      why: 'Correta. Além do efeito do trabalho noturno em si, o desenho da escala modula a intensidade da dessincronização e dos agravos associados.' },
    { t: 'Os efeitos do trabalho noturno se limitam à sonolência durante a jornada, sem repercussão orgânica.', ok: false,
      why: 'Errada. Há repercussões metabólicas, cardiovasculares, digestivas e de saúde mental descritas.' },
    { t: 'A adaptação completa do ritmo circadiano ocorre em todos os trabalhadores após algumas semanas de turno fixo noturno.', ok: false,
      why: 'Errada. A adaptação completa é incomum, especialmente porque nos dias de folga o trabalhador retorna ao padrão diurno.' },
    { t: 'O sentido do rodízio das escalas é irrelevante do ponto de vista fisiológico.', ok: false,
      why: 'Errada. O sentido do rodízio interfere na adaptação e é considerado no planejamento de escalas.' },
    { t: 'Cochilos programados são sempre contraindicados em atividades noturnas.', ok: false,
      why: 'Errada. Cochilos programados são estratégia reconhecida de mitigação da sonolência em algumas atividades.' }
  ],
  comentario: 'Trabalho em turnos: dessincronização circadiana com repercussão no sono, no metabolismo, no aparelho cardiovascular e digestivo e na saúde mental. Desenho da escala importa: sentido do rodízio, velocidade de alternância, duração dos turnos e intervalos de recuperação.',
  pegadinha: 'A ideia de que o trabalhador "se acostuma" com o turno noturno é largamente desmentida — a alternância com dias de folga diurnos impede a adaptação completa.',
  refs: ['Cronobiologia e trabalho em turnos', 'Fisiologia do trabalho'] },

{ id: 'q-4.2-037', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de curtume apresenta hematúria macroscópica indolor. Trabalha há 22 anos em setor com uso histórico de corantes derivados de aminas aromáticas. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A hipótese principal é neoplasia de bexiga relacionada à exposição a aminas aromáticas, com latência longa, e a investigação deve prosseguir mesmo que a exposição tenha cessado há anos.', ok: true,
      why: 'Correta. Hematúria indolor em exposto a aminas aromáticas é sinal de alarme para tumor urotelial, e o longo intervalo desde a exposição é compatível com a latência esperada.' },
    { t: 'Hematúria indolor em trabalhador é habitualmente benigna e dispensa investigação.', ok: false,
      why: 'Errada. Hematúria macroscópica indolor é sinal de alarme para neoplasia urotelial em qualquer contexto.' },
    { t: 'O tempo transcorrido desde a exposição afasta a possibilidade de nexo.', ok: false,
      why: 'Errada. Latência de décadas é característica dessa neoplasia ocupacional.' },
    { t: 'As aminas aromáticas estão associadas principalmente a neoplasia renal parenquimatosa.', ok: false,
      why: 'Errada. A associação clássica é com o carcinoma urotelial de bexiga.' },
    { t: 'A ausência de tabagismo torna desnecessária a investigação.', ok: false,
      why: 'Errada. O tabagismo é fator de risco importante, mas sua ausência aumenta, e não diminui, o peso da hipótese ocupacional.' }
  ],
  comentario: 'Aminas aromáticas (benzidina, beta-naftilamina e derivados) causam câncer de bexiga com latência de décadas. Hematúria indolor é o sinal de alarme. A cessação antiga da exposição não afasta o nexo e justifica vigilância de expostos.',
  pegadinha: 'A ausência de tabagismo é usada como argumento para não investigar, quando na verdade fortalece a hipótese ocupacional.',
  refs: ['IARC Monographs', 'Atlas do Câncer Relacionado ao Trabalho'] },

{ id: 'q-4.2-038', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador rural com exposição a organofosforados chega com miose, sialorreia, broncorreia, bradicardia e fasciculações. Sobre o quadro e a conduta, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro corresponde a síndrome colinérgica por inibição da acetilcolinesterase, e a prioridade é a descontaminação com remoção de roupas e lavagem da pele, além do suporte ventilatório e do uso de antídoto conforme o quadro.', ok: true,
      why: 'Correta. O conjunto muscarínico e nicotínico define a síndrome colinérgica; descontaminação e controle das secreções respiratórias são prioridades imediatas, ao lado do antídoto.' },
    { t: 'A midríase é achado característico da intoxicação por organofosforados.', ok: false,
      why: 'Errada, é a inversão. A miose é o achado típico, e a midríase aponta para outras síndromes toxicológicas.' },
    { t: 'A descontaminação da pele é dispensável quando a via de exposição foi inalatória.', ok: false,
      why: 'Errada. A absorção cutânea é altamente relevante para esses agentes e a roupa contaminada mantém a exposição.' },
    { t: 'A dosagem de colinesterase deve preceder qualquer conduta terapêutica.', ok: false,
      why: 'Errada. O tratamento é clínico e imediato; a dosagem auxilia na confirmação e no seguimento, mas não pode retardar a conduta.' },
    { t: 'A recuperação é sempre imediata e não há risco de manifestações tardias.', ok: false,
      why: 'Errada. Há descrição de síndrome intermediária e de neuropatia tardia associada a alguns compostos.' }
  ],
  comentario: 'Síndrome colinérgica: miose, sialorreia, lacrimejamento, broncorreia, broncoespasmo, bradicardia, vômitos, diarreia, fasciculações e fraqueza. Descontaminação com remoção de roupas e lavagem da pele é parte do tratamento. Existem manifestações tardias além do quadro agudo.',
  pegadinha: 'Trocar miose por midríase é a inversão de bancada. E esperar exame laboratorial para tratar é o erro de conduta.',
  refs: ['Protocolo de Intoxicação por Agrotóxicos — Ministério da Saúde', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-039', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Operador de retroescavadeira, 15 anos de função, com exposição diária a vibração de corpo inteiro e postura sentada prolongada, apresenta lombalgia crônica com episódios de agudização. Sobre esse cenário, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A vibração de corpo inteiro é fator de risco reconhecido para agravos de coluna lombar, e o controle passa por manutenção do assento e da suspensão, pausas, revisão do tempo de exposição e adequação do veículo, além do cuidado clínico.', ok: true,
      why: 'Correta. A associação é reconhecida e o controle é técnico e organizacional, não apenas assistencial.' },
    { t: 'A vibração de corpo inteiro relaciona-se apenas a fenômenos vasculares nas mãos.', ok: false,
      why: 'Errada. O efeito vascular digital é da vibração localizada mão-braço; a de corpo inteiro atinge sobretudo a coluna.' },
    { t: 'A queixa de lombalgia em operador de máquina deve ser presumida como não ocupacional por sua prevalência na população.', ok: false,
      why: 'Errada. Prevalência elevada não exclui contribuição da exposição, sobretudo com fator de risco documentado.' },
    { t: 'O uso de cinto lombar substitui a adequação do assento e a redução do tempo de exposição.', ok: false,
      why: 'Errada. Dispositivos de uso individual não substituem medidas técnicas sobre a fonte da vibração.' },
    { t: 'A exposição à vibração de corpo inteiro não tem qualquer parâmetro de avaliação, o que impede sua caracterização.', ok: false,
      why: 'Errada. Existem métodos consagrados de medição e avaliação da exposição à vibração, aplicáveis na caracterização.' }
  ],
  comentario: 'Vibração mão-braço: dedos brancos, parestesia, perda de destreza. Vibração de corpo inteiro: coluna lombar, discopatia e lombalgia, típica de operadores de veículos e máquinas. O controle é técnico — assento, suspensão, manutenção — e organizacional, com limitação do tempo de exposição.',
  pegadinha: 'Misturar os efeitos das duas formas de vibração é o erro recorrente. Mão-braço tem alvo vascular e neurológico periférico; corpo inteiro tem alvo axial.',
  refs: ['Agravos por vibração — Ministério da Saúde', 'Higiene Ocupacional — vibração'] },

{ id: 'q-4.2-040', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de abatedouro de aves, 27 anos, cinco anos na função de corte, refere dor na face radial do punho direito com piora ao segurar objetos e ao desviar o punho, com dor intensa à manobra que estira os tendões do polegar. Qual é o diagnóstico e o comentário correto?',
  alts: [
    { t: 'Tenossinovite de De Quervain, que acomete os tendões do compartimento extensor radial do polegar e cuja conduta associa medidas locais à revisão da pega e do desvio ulnar repetitivo da tarefa.', ok: true,
      why: 'Correta. O quadro e a manobra provocativa descritos são específicos desse compartimento, e a exigência de preensão com desvio de punho é o fator ocupacional a modificar.' },
    { t: 'Síndrome do túnel do carpo, confirmada pela dor à preensão.', ok: false,
      why: 'Errada. O túnel do carpo cursa com parestesia noturna no território do mediano, e não com dor localizada na face radial do punho.' },
    { t: 'Dedo em gatilho do polegar, caracterizado pela dor ao desvio ulnar do punho.', ok: false,
      why: 'Errada. O dedo em gatilho cursa com travamento e estalido na flexão do dedo, com nódulo palpável na polia, e não com esse padrão de dor no punho.' },
    { t: 'Cisto sinovial dorsal, que produz dor exclusivamente à flexão do punho.', ok: false,
      why: 'Errada. O cisto sinovial se apresenta como abaulamento, sem a resposta característica à manobra descrita.' },
    { t: 'Artrite reumatoide inicial, sugerida pelo acometimento unilateral de punho.', ok: false,
      why: 'Errada. A artrite reumatoide costuma ser poliarticular e simétrica, com rigidez matinal prolongada, o que não corresponde ao quadro.' }
  ],
  comentario: 'De Quervain: dor na face radial do punho, piora à preensão com desvio ulnar, manobra específica de estiramento dos tendões do polegar positiva. Fator ocupacional: pega com força associada a desvio repetitivo do punho, típica de corte e embalagem.',
  pegadinha: 'Rotular como túnel do carpo qualquer dor de punho em trabalho repetitivo é o vício diagnóstico que o caso denuncia. Localização e manobra provocativa distinguem.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-041', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a exposição ocupacional ao mercúrio metálico em trabalhadores de garimpo e de reparo de equipamentos, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A inalação de vapores de mercúrio metálico produz quadro com tremor de intenção, alterações neurocomportamentais e gengivoestomatite, além de possível comprometimento renal, e a conduta inclui afastamento da exposição e investigação da fonte.', ok: true,
      why: 'Correta. A tríade neurológica, psíquica e bucal é a apresentação clássica do hidrargirismo por vapores, com repercussão renal possível.' },
    { t: 'O mercúrio metálico ingerido de forma acidental é a principal via de intoxicação ocupacional.', ok: false,
      why: 'Errada. A via de importância ocupacional é a inalatória de vapores; o mercúrio metálico ingerido tem absorção digestiva muito limitada.' },
    { t: 'A neuropatia periférica motora com mão caída é o achado mais característico.', ok: false,
      why: 'Errada. Esse é o padrão associado ao chumbo, e não ao mercúrio.' },
    { t: 'Alterações de comportamento e irritabilidade não fazem parte do quadro.', ok: false,
      why: 'Errada. As alterações neurocomportamentais estão entre as manifestações mais características.' },
    { t: 'A ausência de tremor em repouso exclui o diagnóstico.', ok: false,
      why: 'Errada. O tremor característico é de intenção e postural, de modo que a ausência de tremor de repouso nada exclui.' }
  ],
  comentario: 'Hidrargirismo por vapores de mercúrio: tremor de intenção, alterações neurocomportamentais e de personalidade, gengivoestomatite e possível lesão renal glomerular. Via inalatória é a relevante no trabalho. Distinga do chumbo (motor, extensores) e do manganês (parkinsonismo).',
  pegadinha: 'A troca dos padrões neurológicos entre metais é a inversão preferida: chumbo com mão caída, mercúrio com tremor e alteração comportamental, manganês com sinais extrapiramidais.',
  refs: ['Protocolo de Intoxicação por Mercúrio — Ministério da Saúde', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-042', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de ligas metálicas, exposto a poeira de manganês por anos, apresenta bradicinesia, rigidez, alteração da marcha e instabilidade postural, com pouca resposta à levodopa. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere manganismo, parkinsonismo de origem ocupacional que tende a apresentar menor resposta à levodopa e características clínicas distintas da doença de Parkinson idiopática, exigindo afastamento imediato da exposição.', ok: true,
      why: 'Correta. A resposta limitada à levodopa e o contexto de exposição são elementos que apontam para o parkinsonismo secundário ao manganês.' },
    { t: 'A boa resposta à levodopa seria esperada e sua ausência afasta causa ocupacional.', ok: false,
      why: 'Errada, é a inversão. A resposta pobre à levodopa é característica do quadro relacionado ao manganês.' },
    { t: 'O manganês está associado classicamente a neuropatia periférica sensitiva distal.', ok: false,
      why: 'Errada. O alvo característico é o sistema extrapiramidal, e não o nervo periférico.' },
    { t: 'O afastamento da exposição é desnecessário, pois o dano já está estabelecido.', ok: false,
      why: 'Errada. Interromper a exposição é medida indispensável para evitar progressão adicional.' },
    { t: 'O quadro descrito corresponde à intoxicação por dissulfeto de carbono, que produz parkinsonismo com boa resposta a levodopa.', ok: false,
      why: 'Errada. Ainda que o dissulfeto de carbono tenha neurotoxicidade, o quadro extrapiramidal por exposição a poeira metálica em ligas aponta para o manganês.' }
  ],
  comentario: 'Manganismo: parkinsonismo ocupacional com alterações neuropsiquiátricas precoces, marcha característica, resposta limitada à levodopa e evolução que pode persistir após o afastamento. Sempre lembrar de manganês diante de parkinsonismo atípico em trabalhador de solda, siderurgia ou ligas.',
  pegadinha: 'Esperar boa resposta à levodopa para "confirmar parkinsonismo" leva a descartar a causa ocupacional exatamente pelo dado que a sugere.',
  refs: ['Neurologia Ocupacional', 'Protocolos de exposição a metais — Ministério da Saúde'] },

{ id: 'q-4.2-043', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a avaliação de trabalhador com queixa osteomuscular relacionada ao trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A concordância entre a intensidade da dor relatada e a gravidade dos achados de imagem é a regra nesses quadros e deve orientar a decisão sobre incapacidade.', ok: true,
      why: 'É a afirmação FALSA e portanto a resposta. A dissociação clínico-radiológica é frequente, com imagens alteradas em assintomáticos e dor intensa com imagem normal.' },
    { t: 'A avaliação funcional e a comparação com as exigências reais do posto são essenciais para decidir sobre aptidão.', ok: false,
      why: 'Verdadeira. A decisão de aptidão confronta capacidade funcional e demanda específica da tarefa.' },
    { t: 'Fatores psicossociais influenciam a percepção da dor e o prognóstico de retorno ao trabalho.', ok: false,
      why: 'Verdadeira. São reconhecidos como determinantes de cronificação e de dificuldade de retorno.' },
    { t: 'O retorno gradual e monitorado tende a produzir melhores desfechos do que o afastamento prolongado.', ok: false,
      why: 'Verdadeira. O retorno precoce e adaptado é associado a melhor prognóstico funcional.' },
    { t: 'A análise da tarefa real, e não da descrição formal do cargo, é o que permite identificar a exposição.', ok: false,
      why: 'Verdadeira. Descrições formais raramente correspondem ao trabalho efetivamente executado.' }
  ],
  comentario: 'Dissociação clínico-radiológica é regra em quadros osteomusculares. Aptidão se decide pela capacidade funcional confrontada com a demanda real da tarefa. Retorno gradual supera afastamento prolongado, e fatores psicossociais modulam dor e prognóstico.',
  pegadinha: 'A afirmação falsa soa como bom senso clínico. Justamente por isso é a mais perigosa: imagem e sintoma caminham separados nesses quadros.',
  refs: ['Protocolo de LER/DORT — Ministério da Saúde', 'Reabilitação e retorno ao trabalho'] },

{ id: 'q-4.2-044', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de frigorífico exposto a amônia em vazamento apresenta, além do quadro respiratório, lesão ocular e cutânea. Sobre a exposição a agentes irritantes de alta solubilidade, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Gases muito solúveis em água tendem a produzir irritação intensa e precoce de mucosas de vias aéreas superiores, olhos e pele, o que costuma provocar fuga imediata do ambiente e limita, em geral, a lesão pulmonar profunda, salvo em exposições maciças ou com vítima impossibilitada de escapar.', ok: true,
      why: 'Correta. A solubilidade determina o nível da árvore respiratória atingido, e o alerta sensorial precoce dos gases muito solúveis é fator protetor relativo.' },
    { t: 'Gases muito solúveis atingem preferencialmente os alvéolos, poupando as vias aéreas superiores.', ok: false,
      why: 'Errada, é a inversão. Gases de baixa solubilidade é que alcançam as porções distais com pouca advertência sensorial.' },
    { t: 'A ausência de sintomas imediatos após exposição a gás pouco solúvel garante ausência de lesão.', ok: false,
      why: 'Errada. Justamente nos gases pouco solúveis pode haver edema pulmonar de instalação tardia após período assintomático.' },
    { t: 'A conduta em lesão ocular por amônia é neutralizar o agente com solução ácida.', ok: false,
      why: 'Errada. A conduta é irrigação abundante e prolongada; neutralização é contraindicada.' },
    { t: 'Exposição única a irritante não pode gerar quadro respiratório persistente.', ok: false,
      why: 'Errada. Exposição única e maciça a irritante pode produzir hiperresponsividade brônquica persistente.' }
  ],
  comentario: 'Solubilidade orienta o dano: gases muito solúveis (amônia, cloreto de hidrogênio, formaldeído) irritam vias superiores e olhos, com alerta sensorial precoce; gases pouco solúveis (fosgênio, dióxido de nitrogênio, ozônio) atingem alvéolos com risco de edema pulmonar tardio após intervalo assintomático.',
  pegadinha: 'A ausência de sintomas imediatos em exposição a gás pouco solúvel é falsamente tranquilizadora e justifica observação prolongada.',
  refs: ['Toxicologia Ocupacional', 'Emergências químicas'] },

{ id: 'q-4.2-045', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de manutenção de torres de telecomunicação relata queixas inespecíficas e atribui-as à exposição a radiofrequência. Sobre agravos relacionados a radiações não ionizantes, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O principal efeito reconhecido da exposição a radiofrequência em níveis elevados é o térmico, o que orienta a avaliação e o controle; queixas inespecíficas exigem investigação diagnóstica ampla, sem atribuição automática à exposição.', ok: true,
      why: 'Correta. O efeito térmico é o mecanismo estabelecido nesse tipo de exposição, e atribuir sintomas inespecíficos sem investigação leva a erro diagnóstico e a perda de outras causas tratáveis.' },
    { t: 'A radiofrequência é radiação ionizante e produz dano direto ao material genético.', ok: false,
      why: 'Errada. Radiofrequência é radiação não ionizante, sem energia suficiente para ionizar átomos.' },
    { t: 'A exposição a ultravioleta ocupacional não tem qualquer relação com câncer de pele.', ok: false,
      why: 'Errada. A radiação ultravioleta é fator estabelecido de câncer de pele em trabalhadores a céu aberto.' },
    { t: 'A radiação infravermelha não apresenta risco ocular em qualquer intensidade.', ok: false,
      why: 'Errada. Exposição crônica a infravermelho está associada a catarata em trabalhadores de fornos e vidrarias.' },
    { t: 'Laser de uso industrial não requer proteção ocular específica quando o feixe não é visível.', ok: false,
      why: 'Errada. Feixes não visíveis podem causar lesão retiniana grave sem alerta sensorial, o que torna a proteção ainda mais necessária.' }
  ],
  comentario: 'Radiações não ionizantes: ultravioleta (ceratoconjuntivite, câncer de pele, pterígio), infravermelho (catarata), laser (lesão retiniana, inclusive com feixe invisível), radiofrequência e micro-ondas (efeito térmico). Não confundir com radiação ionizante, de mecanismo distinto.',
  pegadinha: 'Atribuir sintomas inespecíficos à exposição sem investigar é tão prejudicial quanto negar o risco: perde-se o diagnóstico real e a confiança do trabalhador.',
  refs: ['Radiações não ionizantes — saúde ocupacional', 'Higiene Ocupacional'] },

{ id: 'q-4.2-046', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a avaliação de trabalhador com suspeita de agravo hematológico ocupacional, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O hemograma seriado com comparação evolutiva é mais informativo que um resultado isolado, pois permite identificar tendência de queda dentro da faixa de normalidade, algo que uma única coleta não revela.', ok: true,
      why: 'Correta. Em mielotoxicidade, a trajetória descendente dos valores tem valor de alerta mesmo antes de qualquer resultado sair da faixa de referência.' },
    { t: 'Um único hemograma dentro da faixa de referência exclui mielotoxicidade.', ok: false,
      why: 'Errada. A comparação com exames anteriores é o que permite detectar alteração precoce.' },
    { t: 'A leucocitose é a alteração mais precoce esperada na exposição a agentes mielotóxicos.', ok: false,
      why: 'Errada. O padrão esperado é de citopenias, sendo a leucopenia com neutropenia uma alteração precoce típica.' },
    { t: 'Alterações hematológicas em expostos só são valorizadas quando acompanhadas de sintomas.', ok: false,
      why: 'Errada. A vigilância existe justamente para detectar alteração antes da manifestação clínica.' },
    { t: 'A avaliação da medula óssea é o exame de rastreamento inicial em todos os expostos.', ok: false,
      why: 'Errada. O rastreamento se faz por hemograma seriado; o mielograma é reservado a casos com indicação específica.' }
  ],
  comentario: 'Vigilância hematológica em expostos a mielotóxicos: hemograma seriado com análise de tendência. Valor isolado dentro da faixa não tranquiliza se houver queda consistente. Alterações precoces incluem leucopenia com neutropenia, macrocitose e plaquetopenia.',
  pegadinha: 'A leitura do exame contra a faixa de referência, e não contra o histórico do próprio trabalhador, é o erro que atrasa a detecção.',
  refs: ['Protocolo do Benzeno — Ministério da Saúde', 'Hematologia Ocupacional'] },

{ id: 'q-4.2-047', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de teleatendimento, 31 anos, apresenta quadro de dor cervical e em ombros com evolução de meses, associada a postura estática prolongada com telefone e teclado, metas rígidas e supervisão por indicadores de tempo. Sobre o caso, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A carga estática postural e os determinantes organizacionais atuam de forma combinada nesses quadros, de modo que a intervenção eficaz exige mudança de mobiliário e equipamento e também revisão de metas, pausas e formas de controle do trabalho.', ok: true,
      why: 'Correta. Intervir apenas no mobiliário sem alterar ritmo, metas e pausas costuma produzir resultado insuficiente.' },
    { t: 'Como não há esforço físico intenso, a origem ocupacional deve ser descartada.', ok: false,
      why: 'Errada. Carga estática mantida e ausência de recuperação produzem adoecimento mesmo sem grandes forças envolvidas.' },
    { t: 'A troca da cadeira por modelo ergonômico resolve integralmente o problema.', ok: false,
      why: 'Errada. Mobiliário adequado é necessário, mas não suficiente diante de determinantes organizacionais.' },
    { t: 'Metas e monitoramento por indicadores não constituem fatores de risco à saúde.', ok: false,
      why: 'Errada. Pressão temporal, metas e vigilância sobre o desempenho são fatores psicossociais reconhecidos.' },
    { t: 'A conduta indicada é o afastamento por tempo indeterminado até remissão completa da dor.', ok: false,
      why: 'Errada. Afastamento prolongado sem intervenção no posto tende a cronificar e dificulta o retorno.' }
  ],
  comentario: 'Trabalho de teleatendimento reúne carga estática, exigência cognitiva, uso vocal, ruído e forte controle organizacional. A intervenção precisa alcançar as duas dimensões: física e organizacional. Ausência de esforço intenso não descarta o adoecimento.',
  pegadinha: 'A ideia de que só há risco osteomuscular onde há esforço físico intenso ignora o papel da carga estática mantida e da ausência de recuperação.',
  refs: ['Ergonomia e organização do trabalho', 'Protocolo de LER/DORT — Ministério da Saúde'] },

{ id: 'q-4.2-048', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de refinaria apresenta episódio de perda de consciência durante manutenção em tanque, com recuperação rápida ao ser retirado. Não houve queimadura nem sinais de irritação de vias aéreas. Qual é a hipótese que deve ser prioritariamente considerada?',
  alts: [
    { t: 'Atmosfera deficiente em oxigênio no espaço confinado, situação em que a asfixia ocorre por deslocamento do oxigênio por outros gases, sem qualquer sinal irritativo prévio, o que a torna especialmente perigosa para os resgatistas.', ok: true,
      why: 'Correta. Asfixiantes simples deslocam o oxigênio sem produzir irritação ou odor de alerta, e a inconsciência pode ser súbita, o que explica a alta mortalidade entre socorristas improvisados.' },
    { t: 'Intoxicação por gás irritante de alta solubilidade, sugerida pela perda de consciência sem lesão de mucosas.', ok: false,
      why: 'Errada. Gases irritantes de alta solubilidade produzem sintomas de mucosas antes de qualquer rebaixamento de consciência.' },
    { t: 'Reação alérgica a vapores de hidrocarbonetos, com broncoespasmo.', ok: false,
      why: 'Errada. Não há descrição de broncoespasmo nem de manifestação alérgica.' },
    { t: 'Como houve recuperação rápida, não é necessária investigação da atmosfera do espaço confinado.', ok: false,
      why: 'Errada. A recuperação ao sair do ambiente é justamente a evidência de que a atmosfera é a causa e exige avaliação imediata.' },
    { t: 'O resgate deve ser realizado imediatamente por qualquer colega presente, sem equipamento específico.', ok: false,
      why: 'Errada. É exatamente essa conduta que produz vítimas adicionais; o resgate exige equipamento autônomo e procedimento estabelecido.' }
  ],
  comentario: 'Espaço confinado: risco de atmosfera deficiente em oxigênio, atmosfera tóxica e inflamável. Asfixiantes simples não avisam — não irritam, muitos não têm odor. Grande parte das mortes é de socorristas que entram sem proteção respiratória autônoma.',
  pegadinha: 'A recuperação rápida ao sair do ambiente parece indicar evento benigno, quando na verdade confirma a causa ambiental e indica risco iminente para os demais.',
  refs: ['Trabalho em espaços confinados', 'Toxicologia Ocupacional'] },

{ id: 'q-4.2-049', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre agravos oftalmológicos relacionados ao trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trabalhadores de fornos e vidrarias, expostos cronicamente a radiação infravermelha, apresentam risco aumentado de catarata, quadro de instalação lenta e indolor, distinto da lesão aguda por ultravioleta.', ok: true,
      why: 'Correta. A catarata associada ao infravermelho é o agravo crônico clássico dessas atividades e contrasta com a lesão corneana aguda produzida pelo ultravioleta.' },
    { t: 'A lesão por ultravioleta em soldadores produz catarata aguda em poucas horas.', ok: false,
      why: 'Errada. O ultravioleta produz lesão corneana aguda; a catarata é processo crônico associado sobretudo ao infravermelho e à radiação ionizante.' },
    { t: 'A conjuntivite química por respingo dispensa irrigação quando o agente é ácido.', ok: false,
      why: 'Errada. A irrigação imediata e prolongada é indicada em qualquer queimadura química ocular.' },
    { t: 'O pterígio não tem qualquer relação com exposição solar ocupacional.', ok: false,
      why: 'Errada. A exposição crônica ao ultravioleta em trabalho a céu aberto é fator associado ao pterígio.' },
    { t: 'A retinopatia por laser é sempre precedida de dor intensa, o que permite o afastamento imediato do trabalhador.', ok: false,
      why: 'Errada. A lesão retiniana por laser costuma ser indolor, o que a torna mais perigosa por não haver alerta sensorial.' }
  ],
  comentario: 'Oftalmologia ocupacional: ultravioleta produz ceratoconjuntivite aguda com latência de horas e, cronicamente, pterígio e neoplasias palpebrais; infravermelho associa-se a catarata; laser causa lesão retiniana indolor; queimaduras químicas exigem irrigação imediata, com álcalis mais graves que ácidos.',
  pegadinha: 'A ausência de dor na lesão por laser é contraintuitiva e explica por que a proteção não pode depender da percepção do trabalhador.',
  refs: ['Oftalmologia Ocupacional', 'Radiações não ionizantes'] },

{ id: 'q-4.2-050', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um trabalhador com diagnóstico de LER/DORT retorna após afastamento previdenciário. O médico do trabalho deve decidir sobre a aptidão para a função anterior. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A decisão deve confrontar a capacidade funcional atual com as exigências reais da tarefa, considerar restrições temporárias, prever retorno gradual e reavaliação, e envolver a adequação do posto, e não apenas o julgamento binário de apto ou inapto.', ok: true,
      why: 'Correta. Aptidão é juízo relacional entre pessoa e tarefa; o retorno bem conduzido inclui restrições, gradualidade, adaptação do posto e reavaliação programada.' },
    { t: 'Havendo alta previdenciária, o trabalhador deve retornar à mesma função sem qualquer restrição.', ok: false,
      why: 'Errada. A alta define a cessação do benefício, não a capacidade para a tarefa específica, que é avaliação do médico do trabalho.' },
    { t: 'Se persistir qualquer sintoma, o trabalhador deve ser considerado inapto de forma definitiva.', ok: false,
      why: 'Errada. Sintoma residual não implica inaptidão; o que importa é a compatibilidade com a demanda funcional, eventualmente adaptada.' },
    { t: 'A decisão de aptidão independe da análise do posto de trabalho.', ok: false,
      why: 'Errada. Sem conhecer a exigência real da tarefa não é possível decidir sobre compatibilidade.' },
    { t: 'A recusa do trabalhador em retornar à mesma função configura, por si, falta disciplinar a ser comunicada.', ok: false,
      why: 'Errada. Cabe ao médico avaliar tecnicamente a situação; transformar questão de saúde em questão disciplinar é desvio de função.' }
  ],
  comentario: 'Retorno ao trabalho é processo, não evento. Envolve avaliação funcional, restrições temporárias, adaptação do posto, gradualidade e reavaliação. Alta previdenciária não equivale a aptidão para a tarefa específica.',
  pegadinha: 'Tratar a alta do benefício como decisão médica sobre aptidão é confusão frequente e transfere ao trabalhador o risco de recidiva.',
  refs: ['Reabilitação e retorno ao trabalho', 'NR-7'] },

{ id: 'q-4.2-051', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de fertilizantes com exposição a poeiras e vapores apresenta epistaxes recorrentes e, ao exame, verifica-se perfuração do septo nasal. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A perfuração do septo nasal é lesão descrita em exposição ocupacional a compostos de cromo hexavalente e a outros agentes corrosivos, funcionando como marcador de exposição e indicando falha do controle no ambiente de trabalho.', ok: true,
      why: 'Correta. Ulceração e perfuração septal são sinais clássicos de exposição a cromatos e a agentes corrosivos, com valor de evento-sentinela.' },
    { t: 'Perfuração septal em trabalhador deve ser atribuída exclusivamente a uso de drogas inalatórias.', ok: false,
      why: 'Errada. Embora seja causa conhecida, a exposição ocupacional a agentes corrosivos é diagnóstico diferencial obrigatório nesse contexto.' },
    { t: 'A lesão é sempre reversível com o afastamento da exposição.', ok: false,
      why: 'Errada. A perfuração instalada é lesão estrutural que não se resolve espontaneamente com o afastamento.' },
    { t: 'A presença dessa lesão não justifica avaliação dos demais trabalhadores do setor.', ok: false,
      why: 'Errada. É achado sentinela e indica avaliar todo o grupo exposto e revisar o controle ambiental.' },
    { t: 'A lesão descrita indica necessariamente neoplasia nasossinusal.', ok: false,
      why: 'Errada. A perfuração por agente corrosivo é lesão distinta de neoplasia, embora alguns agentes ocupacionais também aumentem o risco de tumores nasossinusais.' }
  ],
  comentario: 'Ulceração e perfuração de septo nasal são marcadores de exposição a cromo hexavalente e outros corrosivos. Além do cuidado individual, obrigam a investigar o coletivo e o controle ambiental. Lembrar também que poeira de madeira e níquel se associam a neoplasia nasossinusal.',
  pegadinha: 'Atribuir a perfuração septal apenas a causa não ocupacional é o atalho que faz perder um evento-sentinela evidente.',
  refs: ['Dermatoses e lesões por cromo', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-4.2-052', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a exposição ocupacional a agrotóxicos e seus efeitos crônicos, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A ausência de sintomas agudos após aplicações repetidas garante que não há efeito crônico decorrente da exposição.', ok: true,
      why: 'É a afirmação FALSA e portanto a resposta. Efeitos crônicos podem ocorrer sem episódios agudos prévios, incluindo alterações neurocomportamentais, endócrinas e risco oncológico.' },
    { t: 'A absorção cutânea é via relevante na exposição ocupacional a agrotóxicos.', ok: false,
      why: 'Verdadeira. A via dérmica é frequentemente a principal na aplicação em campo.' },
    { t: 'A reentrada precoce em área tratada é uma das situações de maior risco de exposição.', ok: false,
      why: 'Verdadeira. O intervalo de reentrada existe justamente para reduzir esse risco.' },
    { t: 'A vestimenta de proteção precisa ser compatível com o produto e com as condições de calor da atividade, sob pena de não ser utilizada corretamente.', ok: false,
      why: 'Verdadeira. Desconforto térmico é uma das principais causas de uso inadequado da proteção em campo.' },
    { t: 'A lavagem doméstica de roupas contaminadas pode expor familiares do trabalhador.', ok: false,
      why: 'Verdadeira. É exemplo clássico de exposição paraocupacional.' }
  ],
  comentario: 'Agrotóxicos: exposição predominantemente dérmica, risco em preparo, aplicação, reentrada e lavagem de roupas. Efeitos crônicos existem sem episódios agudos prévios. Exposição paraocupacional de familiares é preocupação real.',
  pegadinha: 'Usar a ausência de intoxicação aguda como prova de segurança é o raciocínio falso que a questão isola.',
  refs: ['Protocolo de Intoxicação por Agrotóxicos — Ministério da Saúde', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-4.2-053', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de tintas, exposto a solventes por 14 anos, apresenta queixa de esquecimento, irritabilidade, dificuldade de concentração e redução de iniciativa, sem sinais focais neurológicos e com exame de imagem sem alterações relevantes. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é compatível com encefalopatia crônica por solventes, cuja avaliação se apoia em história ocupacional detalhada, testes neuropsicológicos e exclusão de outras causas, sendo comum que exames de imagem sejam pouco alterados.', ok: true,
      why: 'Correta. A avaliação neuropsicológica é o instrumento sensível nesse quadro, e a normalidade de exames estruturais é o esperado, não um argumento contra o diagnóstico.' },
    { t: 'A ausência de alteração em imagem exclui o diagnóstico de encefalopatia por solventes.', ok: false,
      why: 'Errada. Trata-se de comprometimento funcional que costuma não ter tradução estrutural evidente.' },
    { t: 'O diagnóstico depende exclusivamente da dosagem sérica do solvente no momento da consulta.', ok: false,
      why: 'Errada. Indicadores biológicos refletem exposição recente e não estabelecem, sozinhos, dano crônico.' },
    { t: 'A conduta é manter o trabalhador na função, uma vez que o quadro é reversível em todos os casos.', ok: false,
      why: 'Errada. A conduta é afastar da exposição, e a reversibilidade é apenas parcial nas formas mais avançadas.' },
    { t: 'Sintomas de humor e cognição em trabalhador devem sempre ser atribuídos a transtorno psiquiátrico primário.', ok: false,
      why: 'Errada. A exposição a neurotóxicos precisa ser considerada no diagnóstico diferencial de quadros cognitivos e afetivos em expostos.' }
  ],
  comentario: 'Encefalopatia crônica por solventes: sintomas cognitivos, afetivos e de personalidade, avaliação por história ocupacional e testes neuropsicológicos, exclusão de outras causas, imagem geralmente pouco contributiva. Conduta central é afastar da exposição, com recuperação apenas parcial nas formas avançadas.',
  pegadinha: 'Rotular o quadro como transtorno psiquiátrico comum é o desfecho mais frequente na prática e faz perder tanto o diagnóstico quanto a oportunidade de intervir no ambiente.',
  refs: ['Neurologia Ocupacional', 'Protocolos de exposição a solventes — Ministério da Saúde'] },

{ id: 'q-4.2-054', tema: '4.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre o conceito de exposição paraocupacional e sua relevância em doenças relacionadas ao trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Refere-se à exposição de pessoas que não exercem a atividade, como familiares que entram em contato com poeiras e resíduos trazidos em roupas e calçados do trabalhador, e é reconhecida em situações como exposição a asbesto, chumbo e agrotóxicos.', ok: true,
      why: 'Correta. Casos de doença em familiares de trabalhadores expostos são descritos e justificam medidas como vestiário com barreira, lavagem no local e proibição de levar uniforme para casa.' },
    { t: 'Trata-se da exposição do trabalhador em atividades secundárias fora do horário contratual.', ok: false,
      why: 'Errada. Esse seria um segundo vínculo de trabalho, não exposição paraocupacional.' },
    { t: 'É conceito sem repercussão prática, pois familiares não desenvolvem doença por essa via.', ok: false,
      why: 'Errada. Há casos documentados de mesotelioma e de intoxicação por chumbo em familiares de trabalhadores expostos.' },
    { t: 'A prevenção depende exclusivamente de orientação verbal ao trabalhador sobre higiene doméstica.', ok: false,
      why: 'Errada. A prevenção depende de medidas na empresa, como troca e lavagem de roupas no próprio local e vestiários com separação de áreas.' },
    { t: 'Aplica-se apenas a agentes biológicos.', ok: false,
      why: 'Errada. Aplica-se especialmente a poeiras e agentes químicos que se depositam em roupas, calçados e cabelos.' }
  ],
  comentario: 'Exposição paraocupacional: o agente sai do local de trabalho em roupas, calçados e cabelos e adoece quem nunca trabalhou na atividade. Descrita com asbesto, chumbo e agrotóxicos. Prevenção é da empresa: vestiário com barreira, higienização no local, proibição de levar uniforme para casa.',
  pegadinha: 'Transferir a prevenção para a orientação doméstica individualiza um risco que se controla na organização do trabalho.',
  refs: ['Vigilância em Saúde do Trabalhador', 'Exposição ao asbesto e ao chumbo — Ministério da Saúde'] },

/* ======================= 4.3 — Pneumologia Ocupacional ======================= */

{ id: 'q-4.3-010', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Ex-trabalhador de estaleiro, 63 anos, 25 anos manipulando isolamento térmico, com dispneia progressiva. Ao exame, estertores crepitantes em bases e baqueteamento digital. Radiografia com opacidades irregulares predominando em campos inferiores e espessamentos pleurais calcificados. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é compatível com asbestose associada a placas pleurais, sendo as placas marcador de exposição e não indicador de gravidade da fibrose parenquimatosa.', ok: true,
      why: 'Correta. Opacidades irregulares de predomínio inferior com crepitações e baqueteamento caracterizam asbestose; as placas indicam exposição ao asbesto, sem correlação obrigatória com a extensão do comprometimento parenquimatoso.' },
    { t: 'O padrão descrito corresponde a silicose, cujas opacidades irregulares predominam em bases.', ok: false,
      why: 'Errada. A silicose produz opacidades arredondadas com predomínio em campos superiores.' },
    { t: 'As placas pleurais são lesões pré-malignas que evoluem para mesotelioma na maioria dos casos.', ok: false,
      why: 'Errada. As placas não são pré-malignas nem evoluem para mesotelioma; são marcadores de exposição.' },
    { t: 'A espirometria esperada mostra distúrbio obstrutivo com resposta ao broncodilatador.', ok: false,
      why: 'Errada. O padrão funcional esperado na asbestose é restritivo, com redução da capacidade de difusão.' },
    { t: 'O tempo decorrido desde o início da exposição é curto demais para o diagnóstico.', ok: false,
      why: 'Errada. A latência da asbestose é longa, habitualmente superior a uma década e meia, plenamente compatível com o caso.' }
  ],
  comentario: 'Asbestose: opacidades irregulares, bases, crepitações em velcro, baqueteamento, padrão restritivo com queda da difusão, latência longa. Placas pleurais são marcador de exposição, geralmente assintomáticas e sem potencial maligno próprio. Silicose é o oposto: arredondadas, ápices.',
  pegadinha: 'Tratar placa pleural como lesão pré-cancerosa é erro conceitual comum e gera conduta e informação equivocadas ao trabalhador.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Classificação radiológica OIT'] },

{ id: 'q-4.3-011', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de 34 anos que atuou por 18 meses no jateamento de peças de vestuário em cabine sem ventilação adequada apresenta dispneia rapidamente progressiva, emagrecimento e radiografia com preenchimento alveolar difuso. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere silicose aguda, forma decorrente de exposição maciça em curto período, com padrão de preenchimento alveolar, evolução rápida e prognóstico reservado.', ok: true,
      why: 'Correta. Exposição intensa em meses a poucos anos produz a forma aguda, com quadro de proteinose alveolar induzida por sílica e evolução desfavorável.' },
    { t: 'O tempo de exposição é curto demais para qualquer forma de silicose.', ok: false,
      why: 'Errada. A forma aguda ocorre justamente com exposições intensas de curta duração.' },
    { t: 'Espera-se radiografia com pequenas opacidades arredondadas em campos superiores e adenopatia calcificada, como na forma crônica.', ok: false,
      why: 'Errada. Esse é o padrão da forma crônica; a aguda cursa com padrão de preenchimento alveolar difuso.' },
    { t: 'O quadro é compatível com asbestose de instalação precoce.', ok: false,
      why: 'Errada. A asbestose exige latência longa e produz padrão intersticial de predomínio basal, não preenchimento alveolar em meses.' },
    { t: 'A remoção da exposição garante regressão completa do quadro.', ok: false,
      why: 'Errada. A forma aguda tem prognóstico reservado e a remoção da exposição não assegura regressão.' }
  ],
  comentario: 'Silicose tem três formas: crônica (mais de dez anos, opacidades arredondadas em ápices), acelerada (poucos anos, progressão rápida) e aguda ou silicoproteinose (exposição maciça em meses, preenchimento alveolar, prognóstico ruim). Jateamento é a atividade de maior intensidade de exposição.',
  pegadinha: 'Usar o tempo curto de exposição para excluir silicose é o erro que a questão testa. Intensidade importa tanto quanto duração.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Vigilância da silicose — Ministério da Saúde'] },

{ id: 'q-4.3-012', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Padeiro, 29 anos, com tosse, sibilância e dispneia que pioram ao longo da semana de trabalho e melhoram nos fins de semana e nas férias. Não tinha sintomas respiratórios antes de iniciar na função, há três anos. Sobre a investigação, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de suspeita de asma ocupacional com período de latência por sensibilização à farinha, e a monitorização seriada do pico de fluxo expiratório em períodos de trabalho e de afastamento é ferramenta útil na investigação.', ok: true,
      why: 'Correta. O padrão temporal e o surgimento após início na função apontam para sensibilização; o registro seriado do pico de fluxo comparando trabalho e afastamento é instrumento consagrado.' },
    { t: 'A melhora nos fins de semana afasta a origem ocupacional.', ok: false,
      why: 'Errada, é uma inversão. A melhora no afastamento é justamente o dado que sustenta a suspeita.' },
    { t: 'O diagnóstico deve ser de asma agravada pelo trabalho, uma vez que qualquer asma piora com poeiras.', ok: false,
      why: 'Errada. Asma agravada pelo trabalho pressupõe asma preexistente, ausente neste caso, em que os sintomas iniciaram após o ingresso na função.' },
    { t: 'A conduta adequada é manter o trabalhador na função com uso contínuo de broncodilatador.', ok: false,
      why: 'Errada. Em asma por sensibilização, a conduta é cessar a exposição ao agente, pois doses mínimas passam a desencadear crises.' },
    { t: 'Como não há período de latência em asma ocupacional, o intervalo de três anos exclui o diagnóstico.', ok: false,
      why: 'Errada. A forma por sensibilização tem justamente um período de latência, que pode durar de semanas a anos.' }
  ],
  comentario: 'Asma ocupacional com latência: sensibilização a agente do trabalho, sintomas que pioram na semana e melhoram no afastamento, período assintomático inicial. Investigação com pico de fluxo seriado e, quando disponível, provocação específica. Conduta: cessar exposição, não apenas reduzir.',
  pegadinha: 'A distinção entre asma ocupacional verdadeira e asma agravada pelo trabalho depende de haver ou não asma antes da exposição — e muda o enquadramento e a conduta.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Diretrizes de asma ocupacional'] },

{ id: 'q-4.3-013', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de limpeza sofre exposição única e maciça a vapores de cloro após mistura acidental de produtos, evoluindo em poucas horas com tosse, dispneia e sibilância que persistem por meses, com hiperresponsividade brônquica documentada. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro corresponde à síndrome de disfunção reativa das vias aéreas, forma de asma ocupacional sem período de latência, desencadeada por exposição única a irritante em alta concentração e sem necessidade de sensibilização prévia.', ok: true,
      why: 'Correta. É a forma de asma ocupacional induzida por irritante, com início logo após exposição única e maciça e sintomas persistentes com hiperresponsividade.' },
    { t: 'Trata-se de asma ocupacional por sensibilização, com período de latência abreviado.', ok: false,
      why: 'Errada. Não há sensibilização nem latência nesse mecanismo; o dano é irritativo direto.' },
    { t: 'Como houve exposição única, não pode haver doença respiratória persistente.', ok: false,
      why: 'Errada. A persistência dos sintomas por meses após exposição única é característica da síndrome.' },
    { t: 'A conduta é o retorno imediato à mesma atividade, já que não há sensibilização envolvida.', ok: false,
      why: 'Errada. A hiperresponsividade instalada torna o trabalhador vulnerável a irritantes inespecíficos, exigindo avaliação do ambiente e das exposições.' },
    { t: 'O quadro corresponde a pneumonite de hipersensibilidade aguda.', ok: false,
      why: 'Errada. A pneumonite de hipersensibilidade cursa com quadro sistêmico e alterações intersticiais, e não com obstrução brônquica persistente por irritante.' }
  ],
  comentario: 'Duas rotas para asma ocupacional: com latência, por sensibilização a agentes de alto ou baixo peso molecular; e sem latência, por irritante em exposição única e maciça (síndrome de disfunção reativa das vias aéreas). Distinta da asma agravada pelo trabalho, que pressupõe asma prévia.',
  pegadinha: 'Exigir período de latência para toda asma ocupacional faz perder a forma induzida por irritante, que é justamente a de nexo mais evidente.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Diretrizes de asma ocupacional'] },

{ id: 'q-4.3-014', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Criador de aves, 47 anos, apresenta episódios recorrentes de febre, tosse seca, dispneia e mal-estar que surgem algumas horas após períodos no galpão e melhoram quando permanece dias fora. Tomografia mostra vidro fosco difuso com nódulos centrolobulares e áreas de aprisionamento aéreo. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro sugere pneumonite de hipersensibilidade, cujo diagnóstico se apoia na relação temporal com a exposição, no padrão tomográfico e na resposta ao afastamento, sendo a presença de precipitinas indicativa de exposição e não de doença.', ok: true,
      why: 'Correta. A sequência temporal, o padrão de imagem e a melhora com o afastamento são os pilares diagnósticos; anticorpos séricos apenas atestam contato com o antígeno.' },
    { t: 'O quadro febril recorrente exclui doença ocupacional e indica infecção respiratória de repetição.', ok: false,
      why: 'Errada. A febre com relação temporal estrita à exposição é característica da forma aguda dessa doença.' },
    { t: 'A presença de precipitinas séricas confirma o diagnóstico de forma isolada.', ok: false,
      why: 'Errada. Precipitinas indicam exposição ao antígeno; muitos expostos assintomáticos as apresentam.' },
    { t: 'Trata-se de asma ocupacional, dada a relação com o ambiente de trabalho.', ok: false,
      why: 'Errada. A asma cursa com obstrução e sibilância, sem febre nem padrão intersticial em vidro fosco.' },
    { t: 'A manutenção da exposição com uso de corticoide sistêmico é a conduta de escolha.', ok: false,
      why: 'Errada. O afastamento do antígeno é a base do tratamento; corticoide é adjuvante e não substitui a remoção da exposição.' }
  ],
  comentario: 'Pneumonite de hipersensibilidade: quadro sistêmico e respiratório horas após a exposição, melhora no afastamento, vidro fosco com nódulos centrolobulares e aprisionamento aéreo, linfocitose no lavado broncoalveolar. Precipitinas indicam exposição, não doença. Tratamento essencial é afastar o antígeno.',
  pegadinha: 'A febre faz o candidato pensar em infecção. A chave é a repetição sincronizada com a exposição e a melhora nos períodos fora do ambiente.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Doenças intersticiais ocupacionais'] },

{ id: 'q-4.3-015', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de fiação de algodão relata opressão torácica e dispneia que aparecem no primeiro dia de trabalho da semana e diminuem nos dias seguintes, reaparecendo após períodos de folga prolongada. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro é típico de bissinose, cuja marca é a piora no primeiro dia da semana de trabalho, com atenuação nos dias subsequentes, e que pode evoluir para obstrução crônica se a exposição persistir.', ok: true,
      why: 'Correta. O padrão de sintomas no retorno após a folga é a assinatura clínica da bissinose, e a manutenção da exposição leva a comprometimento obstrutivo permanente.' },
    { t: 'Trata-se de asma ocupacional por sensibilização, com piora progressiva ao longo da semana.', ok: false,
      why: 'Errada. Na asma por sensibilização os sintomas tendem a acumular-se ao longo da semana, e não a atenuar-se.' },
    { t: 'O quadro corresponde a febre dos fumos metálicos, comum em trabalhadores têxteis.', ok: false,
      why: 'Errada. A febre dos fumos metálicos ocorre em soldagem e fusão de metais, especialmente com zinco, e não em fiação de algodão.' },
    { t: 'O padrão descrito indica angina de retirada por nitratos.', ok: false,
      why: 'Errada. Aquele quadro é cardiovascular, ocorre em expostos a ésteres de nitrato e melhora ao retornar à exposição, não ao permanecer nela dias seguidos.' },
    { t: 'A bissinose é doença restritiva sem repercussão obstrutiva.', ok: false,
      why: 'Errada. O comprometimento é obstrutivo, com queda de fluxos ao longo do turno de retorno.' }
  ],
  comentario: 'Bissinose: poeira de algodão, linho e cânhamo. Opressão torácica no primeiro dia após a folga, atenuação nos dias seguintes por tolerância, retorno após novo intervalo. Comprometimento obstrutivo, com queda de fluxos no turno. Exposição persistente leva a obstrução crônica.',
  pegadinha: 'Vários quadros ocupacionais têm "padrão de segunda-feira", com mecanismos e sentidos opostos. Bissinose e febre dos fumos metálicos pioram no retorno; angina por nitratos piora no afastamento.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Doenças respiratórias por poeiras orgânicas'] },

{ id: 'q-4.3-016', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a classificação radiológica internacional das pneumoconioses aplicada à leitura de radiografias de tórax de trabalhadores expostos, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A classificação padroniza a descrição das alterações por comparação com radiografias de referência, registrando forma e tamanho das pequenas opacidades, profusão, zonas acometidas, grandes opacidades e alterações pleurais, e destina-se principalmente à vigilância e à epidemiologia.', ok: true,
      why: 'Correta. O método é comparativo com filmes padrão e produz uma descrição padronizada; sua finalidade primária é epidemiológica e de vigilância, e não o diagnóstico isolado.' },
    { t: 'A classificação substitui a história ocupacional no diagnóstico de pneumoconiose.', ok: false,
      why: 'Errada. O diagnóstico exige história de exposição compatível; a classificação apenas descreve a imagem de modo padronizado.' },
    { t: 'A leitura pode ser realizada sem comparação com radiografias de referência, bastando a descrição livre do radiologista.', ok: false,
      why: 'Errada. A comparação com os filmes padrão é a essência do método e o que garante a padronização.' },
    { t: 'Pequenas opacidades arredondadas e irregulares recebem a mesma designação, pois o formato não tem valor discriminativo.', ok: false,
      why: 'Errada. O formato é registrado com símbolos distintos e tem valor na diferenciação entre padrões de pneumoconiose.' },
    { t: 'A classificação dispensa a avaliação da qualidade técnica da radiografia.', ok: false,
      why: 'Errada. O registro da qualidade técnica é parte obrigatória do método, pois imagem inadequada compromete a leitura.' }
  ],
  comentario: 'A leitura padronizada registra qualidade técnica, forma e tamanho das pequenas opacidades, profusão por comparação com filmes de referência, zonas acometidas, grandes opacidades e alterações pleurais. É ferramenta de vigilância; o diagnóstico soma imagem, exposição e clínica.',
  pegadinha: 'Tratar a classificação como diagnóstico é o erro conceitual. Ela descreve a imagem; quem diagnostica é o conjunto com a história ocupacional.',
  refs: ['Classificação radiológica OIT', 'Santos, U.P. — Pneumologia Ocupacional'] },

{ id: 'q-4.3-017', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Mineiro de carvão, 58 anos, 30 anos de subsolo, apresenta radiografia com pequenas opacidades arredondadas em campos superiores e, em exame subsequente, grandes opacidades bilaterais com retração. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A evolução descrita corresponde à fibrose maciça progressiva, complicação da pneumoconiose com coalescência de pequenas opacidades em grandes massas, associada a perda funcional importante e possível progressão após cessada a exposição.', ok: true,
      why: 'Correta. A confluência das pequenas opacidades em grandes massas caracteriza a forma complicada, com repercussão funcional relevante e progressão possível mesmo sem nova exposição.' },
    { t: 'A presença de grandes opacidades indica necessariamente neoplasia pulmonar.', ok: false,
      why: 'Errada. Embora a diferenciação com neoplasia seja parte da avaliação, as grandes opacidades da forma complicada são achado próprio da pneumoconiose.' },
    { t: 'A pneumoconiose dos trabalhadores do carvão nunca evolui para formas complicadas.', ok: false,
      why: 'Errada. A evolução para a forma complicada é bem descrita nessa pneumoconiose.' },
    { t: 'A cessação da exposição impede qualquer progressão radiológica adicional.', ok: false,
      why: 'Errada. A progressão após o afastamento é conhecida nas pneumoconioses fibrogênicas.' },
    { t: 'A conduta indicada é observação sem qualquer avaliação funcional ou de complicações.', ok: false,
      why: 'Errada. Avaliação funcional, pesquisa de complicações e acompanhamento são parte do manejo.' }
  ],
  comentario: 'Fibrose maciça progressiva: coalescência de pequenas opacidades em grandes massas, com retração e perda funcional. Ocorre na silicose e na pneumoconiose dos trabalhadores do carvão. Progride mesmo após afastamento e exige diferenciação com neoplasia e tuberculose.',
  pegadinha: 'Grandes opacidades em exposto a poeira mineral não autorizam nem o diagnóstico automático de câncer nem o descarte da hipótese: a investigação de tuberculose e de neoplasia faz parte do manejo.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Classificação radiológica OIT'] },

{ id: 'q-4.3-018', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a associação entre silicose e tuberculose, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A silicose não altera o risco de tuberculose, de modo que a investigação da doença infecciosa nesses pacientes segue apenas os critérios da população geral.', ok: true,
      why: 'É a afirmação FALSA e por isso a resposta. O silicótico tem risco substancialmente aumentado de tuberculose, o que exige investigação ativa e vigilância diferenciada.' },
    { t: 'A piora clínica ou radiológica de um silicótico deve levantar a suspeita de tuberculose associada.', ok: false,
      why: 'Verdadeira. É uma das principais causas de deterioração nesses pacientes.' },
    { t: 'O diagnóstico de tuberculose no silicótico pode ser dificultado pelas alterações radiológicas prévias.', ok: false,
      why: 'Verdadeira. A imagem de base confunde a interpretação e exige investigação microbiológica cuidadosa.' },
    { t: 'A exposição à sílica, mesmo sem silicose estabelecida, associa-se a aumento do risco de tuberculose.', ok: false,
      why: 'Verdadeira. O risco aumentado é descrito também em expostos sem doença radiologicamente definida.' },
    { t: 'A investigação de infecção latente tem papel relevante no acompanhamento de expostos e de silicóticos.', ok: false,
      why: 'Verdadeira. A abordagem da infecção latente integra o cuidado desse grupo de maior risco.' }
  ],
  comentario: 'Sílica compromete a função macrofágica e aumenta o risco de tuberculose, com ou sem silicose radiológica estabelecida. Toda deterioração clínica ou radiológica em silicótico exige investigação para tuberculose, e a abordagem da infecção latente é parte do cuidado.',
  pegadinha: 'A afirmação falsa é construída em tom de normalidade clínica. O ponto que a derruba é que a associação silicose e tuberculose é uma das mais consagradas da pneumologia ocupacional.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Manual de Tuberculose — Ministério da Saúde'] },

{ id: 'q-4.3-019', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador com 20 anos de exposição a poeira mineral realiza espirometria que mostra redução proporcional dos volumes com relação entre volume expiratório forçado no primeiro segundo e capacidade vital forçada preservada. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O achado sugere padrão restritivo, mas a confirmação de restrição exige medida dos volumes pulmonares, pois a espirometria isolada apenas levanta a suspeita.', ok: true,
      why: 'Correta. A espirometria sugere restrição quando há redução da capacidade vital com relação preservada, porém a confirmação formal depende da medida da capacidade pulmonar total.' },
    { t: 'O achado confirma distúrbio obstrutivo, pois há redução do volume expiratório forçado no primeiro segundo.', ok: false,
      why: 'Errada. Obstrução se caracteriza pela redução da relação entre esse volume e a capacidade vital forçada, o que não ocorre aqui.' },
    { t: 'A espirometria normal excluiria pneumoconiose.', ok: false,
      why: 'Errada. Pneumoconiose em fase inicial cursa frequentemente com espirometria normal.' },
    { t: 'A ausência de resposta ao broncodilatador afasta doença pulmonar ocupacional.', ok: false,
      why: 'Errada. A resposta ao broncodilatador avalia reversibilidade da obstrução e nada informa sobre doenças intersticiais ocupacionais.' },
    { t: 'A qualidade técnica do exame é irrelevante quando o resultado é compatível com a suspeita clínica.', ok: false,
      why: 'Errada. Critérios de aceitabilidade e reprodutibilidade são condição para qualquer interpretação; exame mal executado simula alterações.' }
  ],
  comentario: 'Espirometria: obstrução quando a relação entre volume expiratório no primeiro segundo e capacidade vital forçada está reduzida; sugestão de restrição quando há queda da capacidade vital com relação preservada, cuja confirmação exige volumes pulmonares. Exame normal não exclui pneumoconiose.',
  pegadinha: 'Concluir restrição apenas pela espirometria é o erro técnico mais comum; ela sugere, os volumes pulmonares confirmam.',
  refs: ['Diretrizes de espirometria', 'Santos, U.P. — Pneumologia Ocupacional'] },

{ id: 'q-4.3-020', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a doença pleural relacionada ao asbesto, assinale a alternativa CORRETA:',
  alts: [
    { t: 'As placas pleurais localizam-se predominantemente na pleura parietal, poupando habitualmente os ápices e os seios costofrênicos, costumam ser assintomáticas e podem calcificar com o tempo, funcionando como marcador de exposição.', ok: true,
      why: 'Correta. A distribuição descrita, o caráter assintomático e a calcificação tardia compõem o quadro típico das placas, cujo valor é de marcador de exposição.' },
    { t: 'O derrame pleural benigno relacionado ao asbesto é manifestação tardia, surgindo apenas décadas após a exposição.', ok: false,
      why: 'Errada. É considerada a manifestação pleural mais precoce, podendo ocorrer nos primeiros anos após a exposição.' },
    { t: 'As placas pleurais causam habitualmente restrição funcional grave.', ok: false,
      why: 'Errada. As placas costumam ter pouca ou nenhuma repercussão funcional; o espessamento pleural difuso é que pode gerar restrição relevante.' },
    { t: 'A presença de placas pleurais confirma o diagnóstico de asbestose.', ok: false,
      why: 'Errada. Placas indicam exposição; asbestose é fibrose parenquimatosa e exige achados próprios.' },
    { t: 'O mesotelioma relacionado ao asbesto tem forte associação com o tabagismo.', ok: false,
      why: 'Errada. Diferentemente do câncer de pulmão, o mesotelioma não apresenta associação relevante com o tabaco.' }
  ],
  comentario: 'Espectro pleural do asbesto: derrame pleural benigno (mais precoce, exsudato, diagnóstico de exclusão), placas pleurais (parietais, poupam ápices e seios, marcador de exposição), espessamento pleural difuso (pode causar restrição), atelectasia redonda e mesotelioma (latência longa, sem relação com tabaco).',
  pegadinha: 'Duas confusões clássicas: achar que placa é igual a asbestose e atribuir ao mesotelioma a mesma sinergia com o tabaco que existe no câncer de pulmão.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Doenças relacionadas ao asbesto — Ministério da Saúde'] },

{ id: 'q-4.3-021', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador exposto simultaneamente a asbesto e com história de tabagismo de longa data desenvolve câncer de pulmão. Sobre a interação entre esses fatores, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A interação entre asbesto e tabagismo no risco de câncer de pulmão é mais do que aditiva, o que reforça a importância tanto do controle da exposição quanto da cessação do tabagismo, sem que o tabagismo afaste o nexo ocupacional.', ok: true,
      why: 'Correta. A combinação multiplica o risco em relação a cada fator isolado, e a presença do tabagismo não elimina a contribuição do asbesto.' },
    { t: 'O tabagismo elimina a contribuição do asbesto, tornando o câncer doença exclusivamente comum.', ok: false,
      why: 'Errada. A contribuição do agente ocupacional persiste e a interação amplifica o risco.' },
    { t: 'O efeito conjunto dos dois fatores é apenas a soma dos riscos isolados.', ok: false,
      why: 'Errada. A interação descrita é superior à simples soma dos riscos.' },
    { t: 'Como o mesotelioma não se associa ao tabaco, o câncer de pulmão também não teria relação com o fumo em expostos ao asbesto.', ok: false,
      why: 'Errada. São tumores diferentes: o mesotelioma não se associa ao tabaco, mas o câncer de pulmão sim, com interação relevante.' },
    { t: 'A cessação do tabagismo em ex-exposto ao asbesto não altera o risco futuro.', ok: false,
      why: 'Errada. A cessação reduz o risco e é uma das intervenções mais efetivas no acompanhamento desses trabalhadores.' }
  ],
  comentario: 'Asbesto e tabaco interagem no câncer de pulmão de forma superior à aditiva. Mesotelioma, ao contrário, não se relaciona ao tabaco. Consequência prática: em expostos, cessação do tabagismo é intervenção de alto impacto, e o hábito não serve como argumento para negar nexo.',
  pegadinha: 'A pergunta explora a diferença entre os dois tumores do asbesto quanto ao tabagismo. Tratá-los como um bloco único leva ao erro nas duas direções.',
  refs: ['IARC Monographs', 'Santos, U.P. — Pneumologia Ocupacional'] },

{ id: 'q-4.3-022', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de pintura automotiva com uso de tintas à base de poliuretano apresenta quadro de tosse e dispneia com sibilos, iniciados após um ano na função. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Isocianatos são agentes de baixo peso molecular classicamente associados a asma ocupacional por sensibilização, na qual concentrações muito baixas passam a desencadear sintomas após instalada a sensibilização, o que torna a remoção da exposição a conduta necessária.', ok: true,
      why: 'Correta. Os isocianatos são a causa mais citada de asma ocupacional por agentes de baixo peso molecular, e o sensibilizado reage a níveis mínimos.' },
    { t: 'Agentes de baixo peso molecular não causam asma ocupacional, que se restringe a proteínas de alto peso molecular.', ok: false,
      why: 'Errada. Agentes de baixo peso molecular são causa reconhecida e frequente, com os isocianatos como exemplo principal.' },
    { t: 'A manutenção da exposição com uso de respirador é conduta suficiente após o diagnóstico.', ok: false,
      why: 'Errada. Em sensibilização, a proteção respiratória não assegura ausência de sintomas nem impede a progressão.' },
    { t: 'A ausência de eosinofilia e de testes cutâneos positivos exclui a asma ocupacional por isocianatos.', ok: false,
      why: 'Errada. Muitos casos por agentes de baixo peso molecular não são mediados por mecanismo demonstrável em testes cutâneos convencionais.' },
    { t: 'Como o quadro apareceu após um ano de trabalho, deve ser classificado como doença comum sem relação ocupacional.', ok: false,
      why: 'Errada. O intervalo é compatível com o período de sensibilização característico dessa forma de asma ocupacional.' }
  ],
  comentario: 'Asma ocupacional por sensibilização: agentes de alto peso molecular (farinha, animais, látex, enzimas) e de baixo peso molecular (isocianatos, anidridos, persulfatos, madeiras, aminas, glutaraldeído). Nos de baixo peso, testes cutâneos e marcadores costumam ser negativos, o que não exclui o diagnóstico.',
  pegadinha: 'Exigir demonstração de mecanismo alérgico por testes convencionais para aceitar asma ocupacional exclui justamente os agentes químicos mais implicados.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Diretrizes de asma ocupacional'] },

{ id: 'q-4.3-023', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre a diferenciação entre asma ocupacional e asma agravada pelo trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Na asma ocupacional a doença é causada por agente presente no trabalho, ao passo que na asma agravada pelo trabalho existe asma preexistente cujos sintomas pioram por irritantes, esforço, frio ou outros fatores do ambiente laboral, com implicações distintas de conduta e de enquadramento.', ok: true,
      why: 'Correta. A diferença está na origem da doença, e ela determina se a conduta é remover o agente sensibilizante ou controlar irritantes e a asma de base.' },
    { t: 'As duas condições são equivalentes e devem receber a mesma conduta.', ok: false,
      why: 'Errada. A conduta difere: sensibilização exige cessar exposição ao agente; agravamento admite controle ambiental e otimização do tratamento.' },
    { t: 'Na asma agravada pelo trabalho não há qualquer relação com o ambiente laboral.', ok: false,
      why: 'Errada. Há relação clara, mas de agravamento de doença preexistente, e não de causação.' },
    { t: 'A asma ocupacional nunca melhora com o afastamento.', ok: false,
      why: 'Errada. A melhora no afastamento é característica, ainda que possa haver sintomas residuais persistentes.' },
    { t: 'A distinção depende exclusivamente do resultado da espirometria.', ok: false,
      why: 'Errada. A distinção se baseia sobretudo na história de existência ou não de asma antes da exposição e no comportamento dos sintomas.' }
  ],
  comentario: 'Asma ocupacional: causada pelo trabalho, com ou sem latência. Asma agravada pelo trabalho: preexistente e piorada por condições laborais. A pergunta que separa as duas é simples: havia asma antes de iniciar a atividade? A resposta muda conduta e enquadramento.',
  pegadinha: 'Assumir que toda asma que piora no trabalho é asma ocupacional leva a conduta e nexo equivocados nos dois sentidos.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Diretrizes de asma ocupacional'] },

{ id: 'q-4.3-024', tema: '4.3', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Soldador que trabalha com material galvanizado apresenta, algumas horas após a jornada, febre, calafrios, mialgia, cefaleia e gosto metálico, com resolução espontânea em cerca de um dia e recorrência após períodos de folga. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O quadro corresponde à febre dos fumos metálicos, síndrome autolimitada associada a óxidos metálicos, especialmente o zinco, com tolerância que se desenvolve ao longo da semana e reaparecimento após intervalo sem exposição.', ok: true,
      why: 'Correta. A síndrome febril autolimitada após soldagem de material galvanizado, com tolerância e recorrência pós-folga, é a apresentação típica.' },
    { t: 'Trata-se de pneumonite de hipersensibilidade, que evolui invariavelmente para fibrose.', ok: false,
      why: 'Errada. A febre dos fumos metálicos é autolimitada e não deixa sequela fibrótica, ao contrário do que ocorre na forma crônica da pneumonite de hipersensibilidade.' },
    { t: 'O quadro indica pneumoconiose por óxido de ferro em fase aguda.', ok: false,
      why: 'Errada. A siderose é pneumoconiose de acúmulo, sem quadro febril agudo.' },
    { t: 'A ausência de alteração radiológica descarta relação com a atividade de soldagem.', ok: false,
      why: 'Errada. A síndrome cursa habitualmente sem alteração radiológica relevante, o que não afasta o nexo.' },
    { t: 'A febre indica infecção respiratória e o trabalhador deve receber antibioticoterapia empírica.', ok: false,
      why: 'Errada. A relação temporal estrita com a jornada e a resolução espontânea afastam a hipótese infecciosa como primeira explicação.' }
  ],
  comentario: 'Febre dos fumos metálicos: quadro gripal horas após soldagem, gosto metálico, autolimitado, com tolerância ao longo da semana e recidiva após folga. Sem sequela. Diferencia-se da pneumonite de hipersensibilidade, da siderose e de quadros infecciosos.',
  pegadinha: 'Todo quadro febril em trabalhador tende a ser tratado como infecção. A relação temporal com a jornada e a resolução espontânea são o que muda o raciocínio.',
  refs: ['Santos, U.P. — Pneumologia Ocupacional', 'Doenças respiratórias por fumos metálicos'] },

);
